// NE555 Touch-and-Hold Lamp - REFERENCE-ONLY pulse-width meter
//
// IMPORTANT: This sketch is NOT part of the build. The main project is
// PURE ANALOG - the NE555, button, resistor, cap, and LED do everything
// by themselves with no microcontroller. Power the breadboard from a 5V
// USB supply, press the button, and the LED lights for ~11 seconds. Done.
//
// This file is here ONLY if you later want to measure the actual pulse
// width and compare it to the theoretical T = 1.1 * R * C value.
//
// To run this OPTIONAL test you would need (NOT included in the allocations
// for this project, but you already have them in the kit):
//   - 1x Arduino Uno R3
//   - 1x extra Breadboard 4.5x9.5cm (you have qty=2, so this is fine)
//   - A few Jumper Wire F-M (for jumping from Arduino headers to a
//     breadboard rail) - you have a 20pc pack already.
//
// Wiring for the optional measurement:
//   - NE555 pin 3 (OUT)  -> Arduino D2
//   - NE555 GND rail     -> Arduino GND (shared ground is critical)
//
// Then open Serial Monitor at 115200.
//
// Theoretical pulse for R=100K, C=100uF:
//   T = 1.1 * 100,000 ohms * 0.000100 F = 11.0 seconds
//
// Real-world electrolytics drift +/- 20%, so 8.8s to 13.2s is normal.

const int NE555_OUTPUT_PIN = 2;  // Connect to NE555 pin 3 (OUT)
unsigned long pulseStartMs = 0;
bool lastState = LOW;

void setup() {
  Serial.begin(115200);
  pinMode(NE555_OUTPUT_PIN, INPUT);
  Serial.println(F("NE555 monostable pulse-width meter"));
  Serial.println(F("Theoretical T = 1.1 * R * C"));
  Serial.println(F("R=100K, C=100uF -> expected ~11.0 seconds"));
  Serial.println(F("Press the button on the NE555 breadboard..."));
}

void loop() {
  bool now = digitalRead(NE555_OUTPUT_PIN);

  if (now == HIGH && lastState == LOW) {
    // Rising edge - timing pulse just started
    pulseStartMs = millis();
    Serial.println(F(">>> Pulse started (LED ON)"));
  }
  if (now == LOW && lastState == HIGH) {
    // Falling edge - pulse ended, report measurement
    unsigned long durationMs = millis() - pulseStartMs;
    Serial.print(F("<<< Pulse ended. Measured duration: "));
    Serial.print(durationMs / 1000.0, 2);
    Serial.println(F(" seconds"));
    Serial.println(F("---"));
  }
  lastState = now;
}

