// SW-420 Bump Buzzer - OPTIONAL test helper sketch
//
// This project is PURELY ANALOG once built. The NE555 does the timing,
// the active piezo buzzer self-oscillates from DC, the SW-420 does the
// sensing. No MCU is needed to RUN it. The Arduino Uno is wired in only
// to deliver a regulated 5V from its USB rail to the breadboard.
//
// This sketch is OPTIONAL. Load it on the Uno BEFORE building the
// NE555 stage, to confirm the SW-420 is producing clean pulses and to
// help you set the blue threshold pot on the SW-420. After that, lift
// D2 off the SW-420 DO line and use the Uno purely as a 5V source.
//
// Wiring for this test only:
//   SW-420 VCC -> Uno 5V
//   SW-420 GND -> Uno GND
//   SW-420 DO  -> Uno D2

const int SW420_DO_PIN = 2;
unsigned long lastShakeMs = 0;
int shakeCount = 0;

void setup() {
  Serial.begin(115200);
  pinMode(SW420_DO_PIN, INPUT);
  Serial.println(F("SW-420 sanity check - shake the desk."));
  Serial.println(F("DO is active-LOW: idle reads HIGH, shake briefly pulls LOW."));
  Serial.println(F("Turn the blue pot until typing nearby does NOT trigger but a desk-tap does."));
}

void loop() {
  int state = digitalRead(SW420_DO_PIN);
  unsigned long now = millis();

  // 50ms debounce so one shake doesn't get counted ten times
  if (state == LOW && (now - lastShakeMs) > 50) {
    shakeCount++;
    lastShakeMs = now;
    Serial.print(F("SHAKE #"));
    Serial.print(shakeCount);
    Serial.print(F(" at t="));
    Serial.print(now);
    Serial.println(F(" ms"));
  }

  // Periodic heartbeat so you know the sketch is alive
  static unsigned long lastTickMs = 0;
  if (now - lastTickMs > 2000) {
    lastTickMs = now;
    Serial.print(F("[idle] DO="));
    Serial.print(state);
    Serial.print(F(" total shakes="));
    Serial.println(shakeCount);
  }
}

