#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

// --- OLED ---
#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64
#define OLED_RESET   -1
#define OLED_ADDR    0x3C
Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, OLED_RESET);

// --- Signal in ---
// LM358 output (op-amp A, pin 1) feeds A0.
// Op-amp B output (pin 7) is the 2.5V virtual ground that is the reference
// for the transimpedance stage; we also sample it on A1 so we can subtract
// it in software and report a signed photocurrent.
const uint8_t PIN_SIGNAL = A0;
const uint8_t PIN_VREF   = A1;

// --- Circuit constants ---
// Feedback resistor Rf in ohms. With Rf = 47,000 the transimpedance gain
// is ~47 mV per microamp of photocurrent (Vout = -Iphoto * Rf, measured
// relative to the virtual-ground reference).
//
// IMPORTANT: an LDR is a much "leakier" sensor than a real photodiode -
// it can pass tens to hundreds of microamps in normal indoor light. With
// the original 1M feedback resistor the op-amp would slam straight to
// the negative rail and you would see a pinned reading. 47K keeps the
// stage living happily inside the LM358's swing range. If you ever swap
// the LDR for an actual photodiode (BPW34 etc.), THEN you can crank Rf
// back up to 1M-10M to recover sensitivity.
const float RF_OHMS = 47.0e3f;

// Arduino Uno ADC reference (default = AVcc ~ 5.0V) and resolution.
const float ADC_VREF = 5.0f;
const int   ADC_MAX  = 1023;

// Very rough conversion from photocurrent (uA) to lux. The KY-018's LDR is
// nothing like a calibrated photodiode, so this is a learning estimate,
// not a metrology-grade reading. Tune K_LUX_PER_UA empirically against a
// known light source (phone lux-meter app works well enough).
const float K_LUX_PER_UA = 5.0f;

void setup() {
  Serial.begin(115200);
  delay(200);

  if (!display.begin(SSD1306_SWITCHCAPVCC, OLED_ADDR)) {
    Serial.println(F("OLED init failed"));
    while (true) { delay(1000); }
  }
  display.clearDisplay();
  display.setTextColor(SSD1306_WHITE);
  display.setTextSize(1);
  display.setCursor(0, 0);
  display.println(F("LM358 Lux Meter"));
  display.display();
  delay(800);

  // Print expected ranges so the beginner has something to check against.
  Serial.println(F("Boot self-check:"));
  Serial.println(F("  Expect VREF 2.45 - 2.55 V"));
  Serial.println(F("  Expect dV ~ 0 mV when LDR is covered"));
  Serial.println(F("  Expect dV negative (Iph positive) when LDR is lit"));
  Serial.println(F("  If dV pins at -2.5V Rf is too big, drop it lower"));
}

void loop() {
  // Oversample to knock down ADC noise.
  const int N = 32;
  long sumSig = 0, sumRef = 0;
  for (int i = 0; i < N; i++) {
    sumSig += analogRead(PIN_SIGNAL);
    sumRef += analogRead(PIN_VREF);
  }
  float vSignal = (sumSig / (float)N) * ADC_VREF / ADC_MAX;
  float vRef    = (sumRef / (float)N) * ADC_VREF / ADC_MAX;

  // Differential measurement around the virtual ground.
  // More light -> LDR sinks current at the inverting input ->
  // op-amp output swings BELOW vRef. dV is therefore <= 0 in light.
  float dV = vSignal - vRef;

  // Convert to photocurrent in microamps. Sign flip so "more light" reads
  // as a positive photocurrent number.
  float iPhoto_uA = -dV / RF_OHMS * 1.0e6f;
  if (iPhoto_uA < 0) iPhoto_uA = 0;   // clip tiny negative noise

  // Saturation warning: if vSignal is within ~50 mV of GND the op-amp
  // is bottomed out and the reading is no longer linear.
  bool pinned = (vSignal < 0.05f);

  float luxEst = iPhoto_uA * K_LUX_PER_UA;

  // --- Serial debug ---
  Serial.print(F("Vref="));   Serial.print(vRef, 3);
  Serial.print(F("V  Vsig=")); Serial.print(vSignal, 3);
  Serial.print(F("V  dV="));   Serial.print(dV * 1000.0f, 1);
  Serial.print(F("mV  Iph=")); Serial.print(iPhoto_uA, 3);
  Serial.print(F("uA  lux~")); Serial.print(luxEst, 0);
  if (pinned) Serial.print(F("  [PINNED - reduce Rf]"));
  Serial.println();

  // --- OLED display ---
  display.clearDisplay();
  display.setCursor(0, 0);
  display.setTextSize(1);
  display.println(F("LM358 Lux Meter"));
  display.drawFastHLine(0, 10, 128, SSD1306_WHITE);

  display.setCursor(0, 16);
  display.print(F("Vref ")); display.print(vRef, 2); display.println(F(" V"));
  display.print(F("dV   ")); display.print(dV * 1000.0f, 1); display.println(F(" mV"));
  display.print(F("Iph  ")); display.print(iPhoto_uA, 2); display.println(F(" uA"));

  display.setTextSize(2);
  display.setCursor(0, 46);
  if (pinned) {
    display.print(F("PIN!"));
  } else {
    display.print((int)luxEst);
  }
  display.setTextSize(1);
  display.print(F(" lux"));

  display.display();
  delay(200);
}

// LM324 Quad Window Comparator Battery Gauge - Calibration Helper
//
// This is a PURE-ANALOG project - no MCU is required for it to work.
// Use this sketch on an Arduino Uno ONLY if you want to log the battery
// voltage while you verify the four LM324 thresholds trip at the right
// points.
//
// WIRING for the helper:
//   The gauge already has a 10K/10K battery divider (VSENSE node).
//   Tap VSENSE on the gauge DIRECTLY into Uno A0. Do NOT build a second
//   divider - that would double-divide V_batt to V_batt/4 and skew every
//   reading. Also tie Uno GND to the gauge GND so the two share a ground.
//
// Expected trip points with the wiring as drawn (uniform 10K ladder
// between +5V and GND -> taps at 4.00 / 3.00 / 2.00 / 1.00 V):
//   Blue   off below V_batt = 8.0 V  (V_batt/2 < 4.00 V vs 4.00 V ref)
//   Green  off below V_batt = 6.0 V  (V_batt/2 < 3.00 V vs 3.00 V ref)
//   Yellow off below V_batt = 4.0 V  (V_batt/2 < 2.00 V vs 2.00 V ref)
//   Red    off below V_batt = 2.0 V  (effectively always on while powered)
//
// Pin map (matches the wiring diagram):
//   A0  <- VSENSE on the gauge (already = V_batt / 2)
//
// Andy's beginner-friendly debugging companion - not part of the gauge itself.

const int BATT_DIV_PIN = A0;     // reads V_batt / 2 directly from VSENSE
const float ADC_REF    = 5.0;    // Uno's analog reference (default 5V)
const float ADC_STEPS  = 1023.0; // 10-bit ADC

void setup() {
  Serial.begin(115200);
  Serial.println(F("LM324 battery gauge calibration helper"));
  Serial.println(F("Tap VSENSE on the gauge (NOT V_batt) into A0."));
  Serial.println(F("Hold the TEST button on the gauge to power it up."));
  Serial.println(F("Reading V_batt every 500 ms..."));
  Serial.println();
}

void loop() {
  int raw = analogRead(BATT_DIV_PIN);
  float v_half = (raw / ADC_STEPS) * ADC_REF;   // voltage at A0 = V_batt/2
  float v_batt = v_half * 2.0;                  // un-divide

  Serial.print(F("V_batt = "));
  Serial.print(v_batt, 2);
  Serial.print(F(" V   "));

  // Predict which LEDs SHOULD be lit, so you can compare to the real board.
  Serial.print(F("[ "));
  Serial.print(v_batt > 8.0 ? F("BLU ")   : F("--- "));
  Serial.print(v_batt > 6.0 ? F("GRN ")   : F("--- "));
  Serial.print(v_batt > 4.0 ? F("YEL ")   : F("--- "));
  Serial.print(v_batt > 2.0 ? F("RED ")   : F("--- "));
  Serial.println(F("]"));

  delay(500);
}

