// LM386 Pocket Speaker Amp - bench test helper
//
// This sketch is OPTIONAL. The amp is a pure analog circuit and works
// without any microcontroller. Use this only if you want to feed it a
// test tone instead of music from a phone, to confirm the amp itself
// is alive before plugging your phone in.
//
// Wire Arduino Uno pin 9 in place of the phone jack tip - keep the
// existing 1uF cap and 10K resistor in the signal path. So the chain
// is: Uno pin 9 -> existing 1uF -> existing 10K -> LM386 pin 3.
// The 1uF cap is important: it blocks the DC offset from the Uno's
// 5V logic pin, which would otherwise upset the LM386's input bias
// and possibly latch the amp into a stuck state.
//
// Tie Arduino GND to the breadboard GND rail. Leave the amp powered
// from its own 5V USB-C supply - do NOT power the LM386 from the
// Uno's 5V pin (the Uno regulator can't supply the current spikes
// the speaker draws and you'll get audible noise).
//
// Expected result: a clean 1 kHz square-wave beep from the speaker.

const int TONE_PIN = 9;
const int TONE_HZ  = 1000;   // 1 kHz - easy to hear, well inside speaker range
const int BEEP_MS  = 400;
const int GAP_MS   = 600;

void setup() {
  Serial.begin(115200);
  pinMode(TONE_PIN, OUTPUT);
  Serial.println("LM386 bench test - 1 kHz beep every second");
  Serial.println("If you hear nothing:");
  Serial.println(" 1. Check 5V is on LM386 pin 6 and GND on pin 4");
  Serial.println(" 2. Check 220uF output cap polarity (+ to pin 5)");
  Serial.println(" 3. Check the 10uF bypass cap is in place from pin 7 to GND");
  Serial.println(" 4. Touch a finger to pin 3 - speaker should HUM loudly");
  Serial.println("    (your body picks up 50/60 Hz mains - proves gain works)");
}

void loop() {
  tone(TONE_PIN, TONE_HZ);
  delay(BEEP_MS);
  noTone(TONE_PIN);
  delay(GAP_MS);
}

