// TDA2822D Stereo Earbud Amp - test-tone helper (optional)
//
// This project is a pure-analog circuit. The Arduino Uno is OPTIONAL and
// is only used to verify stereo channel separation BEFORE you connect a
// real audio source. Once you've confirmed left and right are not crossed,
// disconnect the Uno and feed audio from a phone or laptop 3.5mm jack:
//   TIP   = LEFT input cap (10uF -> pin 3 IN1+)
//   RING  = RIGHT input cap (10uF -> pin 6 IN2+)
//   SLEEVE= GND rail (battery negative)
//
// Test wiring (TEMPORARY, remove after verification):
//   Uno D9  -> 10K -> LEFT-IN  node (junction at the 10uF input cap)
//   Uno D10 -> 10K -> RIGHT-IN node
//   Uno GND -> amp GND (battery negative)
// The 10K series resistors attenuate the 5V square wave down to a safe
// audio-level signal so you don't blast your ears or saturate the amp.

const int LEFT_PIN  = 9;   // OC1A
const int RIGHT_PIN = 10;  // OC1B

void setup() {
  Serial.begin(115200);
  pinMode(LEFT_PIN, OUTPUT);
  pinMode(RIGHT_PIN, OUTPUT);
  Serial.println(F("TDA2822D test: 440 Hz LEFT, 880 Hz RIGHT."));
  Serial.println(F("Listen: low tone in LEFT bud, high tone in RIGHT bud."));
  tone(LEFT_PIN, 440);
  tone(RIGHT_PIN, 880);
}

void loop() {
  // Swap tones every 2 seconds so you can confirm channels aren't crossed.
  delay(2000);
  noTone(LEFT_PIN); noTone(RIGHT_PIN);
  tone(LEFT_PIN, 880);
  tone(RIGHT_PIN, 440);
  Serial.println(F("Swapped: high LEFT, low RIGHT."));
  delay(2000);
  noTone(LEFT_PIN); noTone(RIGHT_PIN);
  tone(LEFT_PIN, 440);
  tone(RIGHT_PIN, 880);
  Serial.println(F("Normal: low LEFT, high RIGHT."));
}

// ---------------------------------------------------------------
// Multimeter checks (no Uno needed) - do these FIRST, before any
// audio source is connected:
//
//   1. Power off, battery in: measure 9V across the bulk decoupling
//      cap. Confirms battery polarity at the rails.
//   2. Power on, no signal:
//        - Pin 5 (Vcc) -> GND: ~9V.
//        - Pin 4 (GND) -> GND: 0V (sanity check).
//        - Pin 1 (OUT1) and pin 8 (OUT2) DC reading: ~Vcc/2, around
//          4.5V. This is the mid-supply bias the chip applies so the
//          AC signal can swing both up and down.
//        - Pin 3 (IN1+) and pin 6 (IN2+): ~0V (held there through
//          your audio source, or floating low with no source).
//        - Pin 2 (IN1-) and pin 7 (IN2-): a small positive DC voltage
//          (the chip's internal feedback divider sets this).
//   3. The 470uF output caps block the 4.5V DC. The earbud side of
//      each output cap should read ~0V DC. If you read 4.5V on the
//      earbud side, that output cap is wired backwards or open.
//   4. Touch a finger to either input pin (pin 3 or pin 6) briefly.
//      You should hear a low buzz in the matching earbud - that's
//      50/60 Hz mains hum picked up by your body, amplified. Quick
//      proof the amp is alive.
// ---------------------------------------------------------------

