// ULN2803 Knight Rider Light Bar
// 8 LEDs scanned left-to-right and back, driven through a ULN2803 Darlington array.
//
// Wiring (must match the diagram):
//   Arduino D2..D9 -> ULN2803 IN1..IN8
//   ULN2803 OUT1..OUT8 -> LED cathodes (LED1..LED8)
//   LED anodes -> 220R resistor -> +5V rail
//   ULN2803 pin  9 -> GND
//   ULN2803 pin 10 -> +5V (COM, load supply)
//
// Logic note: the ULN2803 is a SINK driver. When an Arduino input pin is HIGH,
// the matching ULN2803 output is pulled to GND, completing the LED circuit and
// turning the LED on. HIGH on the Arduino = LED ON.

const uint8_t LED_PINS[8] = {2, 3, 4, 5, 6, 7, 8, 9};
const uint8_t NUM_LEDS = 8;

// Milliseconds the "dot" stays on each LED.
// Lower = faster scan. Try 30 (fast) or 200 (lazy bounce).
const uint16_t STEP_MS = 80;

int position = 0;   // current lit LED index, 0..NUM_LEDS-1
int direction = 1;  // +1 moves right, -1 moves left

void setup() {
  for (uint8_t i = 0; i < NUM_LEDS; i++) {
    pinMode(LED_PINS[i], OUTPUT);
    digitalWrite(LED_PINS[i], LOW);  // all off at boot
  }
}

void loop() {
  // Turn all LEDs off, then light only the current one.
  for (uint8_t i = 0; i < NUM_LEDS; i++) {
    digitalWrite(LED_PINS[i], LOW);
  }
  digitalWrite(LED_PINS[position], HIGH);

  delay(STEP_MS);

  // Advance the dot. Bounce at the ends instead of wrapping.
  position += direction;
  if (position >= NUM_LEDS - 1) {
    position = NUM_LEDS - 1;
    direction = -1;
  } else if (position <= 0) {
    position = 0;
    direction = 1;
  }
}

