// PC817 Optoisolated Relay Trigger Board
//
// ESP32 NodeMCU-32S drives a PC817 optocoupler LED through a 1K resistor.
// On the load side, the PC817 phototransistor emitter feeds the BC337 base
// directly (with a 10K pull-down keeping the base at GND when the opto is dark).
// The BC337 saturates and sinks the relay-module IN pin to ground, which fires
// the active-LOW 1-channel relay. The relay then closes the green demo-LED
// circuit.
//
// Wiring (MUST match the Mermaid diagram):
//   ESP32 GPIO 23 -> 1K -> PC817 pin 1 (anode)
//   ESP32 GND     ----- PC817 pin 2 (cathode)
//   Load-side +5V (from relay module VCC rail) -> PC817 pin 4 (collector)
//   PC817 pin 3 (emitter) -> BC337 base (direct connection)
//   BC337 base -> 10K pull-down -> load-side GND
//   BC337 emitter -> load-side GND
//   BC337 collector -> Relay module IN
//   Relay module VCC -> load-side +5V, GND -> load-side GND
//   Relay COM -> load-side +5V, NO -> 330R -> Green LED anode -> LED cathode -> load-side GND
//
// IMPORTANT: in the first build the load-side +5V is jumpered from the ESP32
// Vin (USB 5V) rail. That means the two grounds ARE connected, so this build
// is a wiring exercise, not real isolation. The PC817 is in the signal path
// so the bridge is a single wire you cut later - see "Things to change".

const int OPTO_PIN = 23;          // GPIO driving the PC817 LED through 1K
const unsigned long PERIOD_MS = 2000;  // toggle every 2 seconds

void setup() {
  Serial.begin(115200);
  delay(200);
  pinMode(OPTO_PIN, OUTPUT);
  digitalWrite(OPTO_PIN, LOW);    // start with opto dark, relay open
  Serial.println("PC817 Optoisolated Relay Trigger - boot");
  Serial.println("Toggling GPIO 23 every 2 seconds.");
  Serial.println("Listen for the relay click. Watch the green LED.");
}

void loop() {
  digitalWrite(OPTO_PIN, HIGH);   // light PC817 LED -> BC337 on -> relay closes
  Serial.println("OPTO ON  -> relay CLOSED (LED should be lit)");
  delay(PERIOD_MS);

  digitalWrite(OPTO_PIN, LOW);    // PC817 LED off -> BC337 off -> relay opens
  Serial.println("OPTO OFF -> relay OPEN   (LED should be dark)");
  delay(PERIOD_MS);
}

