// BC327 High-Side Load Switch demo for the KY-008 laser.
//
// Pin mapping note (READ THIS): on the XIAO ESP32-C3 silkscreen,
// the pin labelled "D2" is internally GPIO4. The Arduino core for
// this board maps the Dx silk labels to the matching D-number
// constants, so we use the literal 4 here to make it unambiguous
// regardless of how the core's headers are configured.
//
// Wiring summary (must match the Mermaid diagram):
//   XIAO 5V  -> breadboard +5V rail (USB rail, NOT the 3V3 pin)
//   XIAO GND -> breadboard GND rail
//   XIAO D2 (GPIO4) -> 1K -> BC547 base
//   BC547 emitter -> GND
//   BC547 collector -> 1K -> BC327 base
//   BC327 base -> 10K -> +5V (pull-up, keeps laser OFF at boot)
//   BC327 emitter -> +5V
//   BC327 collector -> KY-008 "S" (signal / current-limited input) pin
//   KY-008 GND ("-") -> GND, third pin left disconnected
//
// KY-008 pin identification (clones disagree, so read YOUR silk):
//   Look at the bottom of the module - it is silk-printed with
//   "S", "+" (or middle/VCC), and "-" (GND). Route the BC327
//   collector to "S" only. Leave the unlabeled/middle pin
//   disconnected unless your specific module's silk explicitly
//   tells you to tie it to +5V. Some clones short S to + internally
//   through a current-limit resistor; tying both to +5V on those
//   variants bypasses the limiter and cooks the diode.
//
// Logic recap:
//   GPIO HIGH  -> BC547 ON  -> pulls BC327 base LOW  -> BC327 ON  -> laser ON
//   GPIO LOW   -> BC547 OFF -> 10K pulls BC327 base HIGH -> BC327 OFF -> laser OFF
//
// Safety: do NOT stare into the laser. Aim it at a piece of paper on the bench.

const int CTRL_PIN = 4;  // XIAO ESP32-C3 silk "D2" = GPIO4

void setup() {
  Serial.begin(115200);
  // Pre-load the output latch LOW *before* flipping to OUTPUT so the
  // pin never briefly drives HIGH the instant pinMode() takes effect.
  // The 10K base pull-up is what actually keeps the laser off during
  // the high-Z window before this line runs; this trick just makes
  // the GPIO's first driven state guaranteed-LOW.
  digitalWrite(CTRL_PIN, LOW);
  pinMode(CTRL_PIN, OUTPUT);

  delay(500);
  Serial.println();
  Serial.println("BC327 high-side switch demo");
  Serial.println("HIGH on D2/GPIO4 = laser ON, LOW = laser OFF");
}

void loop() {
  // 1 second on, 1 second off, then a short PWM burst to show
  // the switch is fast enough to dim/blink visibly.
  Serial.println("ON  (1 s)");
  digitalWrite(CTRL_PIN, HIGH);
  delay(1000);

  Serial.println("OFF (1 s)");
  digitalWrite(CTRL_PIN, LOW);
  delay(1000);

  Serial.println("Fast blink burst (2 s @ 10 Hz)");
  for (int i = 0; i < 20; i++) {
    digitalWrite(CTRL_PIN, HIGH);
    delay(50);
    digitalWrite(CTRL_PIN, LOW);
    delay(50);
  }
}

