// ULN2003 Servo Sweep Sentinel
// One Uno GPIO drives 5 LEDs in parallel through a ULN2003,
// while a PIR triggers an alarm hold window and the servo sweeps a flag.
//
// Power architecture (important!):
//  - Uno + LEDs + ULN2003 + PIR run from the Uno's USB-fed 5V rail.
//  - The SG90 servo runs from a SEPARATE 5V supply (a TP4056-style
//    USB-C breakout works). The two grounds MUST be tied together,
//    but the servo's noisy 5V never touches the Uno's 5V rail.

#include <Servo.h>

// ---- Pin map (matches wiring diagram) ----
const uint8_t PIR_PIN     = 2;   // HC-SR501 DOUT
const uint8_t LED_BANK    = 7;   // Drives ULN2003 inputs IN1..IN5 (tied together)
const uint8_t SERVO_PIN   = 9;   // SG90 signal wire (PWM-capable)

// ---- Behaviour tuning ----
const unsigned long ALARM_HOLD_MS = 5000;  // Keep flag sweeping after last motion
const uint8_t  SWEEP_LEFT     = 20;
const uint8_t  SWEEP_RIGHT    = 160;
const uint16_t SWEEP_STEP_MS  = 15;

Servo flag;

// Rollover-safe timing: we store the moment motion was last seen
// and compare elapsed = (millis() - lastMotionAt). Unsigned subtraction
// wraps cleanly across the ~49.7-day millis() rollover, so this stays
// correct forever; `millis() + HOLD` does NOT.
bool          alarmActive   = false;
unsigned long lastMotionAt  = 0;

uint8_t       pos     = 90;
int8_t        dir     = 1;
unsigned long lastStep = 0;

void setLedBank(bool on) {
  // The ULN2003 is an open-collector SINK driver. When LED_BANK goes HIGH,
  // each tied input turns on a Darlington pair inside the chip that pulls
  // its output pin down to near GND. Current then flows: +5V -> 220R -> LED
  // -> ULN output pin -> GND. LEDs light. LED_BANK LOW = outputs float =
  // LEDs dark.
  digitalWrite(LED_BANK, on ? HIGH : LOW);
}

void setup() {
  Serial.begin(115200);

  pinMode(PIR_PIN, INPUT);
  pinMode(LED_BANK, OUTPUT);
  setLedBank(false);

  flag.attach(SERVO_PIN);
  flag.write(90);          // centre / "rest" position

  Serial.println(F("ULN2003 Servo Sweep Sentinel ready."));
  Serial.println(F("Warming up PIR for 30 seconds..."));
  // Blocking delay() is normally a code smell, but it is fine here:
  // we are at boot, nothing else needs to run, and the HC-SR501's
  // pyroelectric element genuinely needs ~30 s to stabilise or it
  // will fire constantly. Anywhere inside loop() we would use millis().
  delay(30000);
  Serial.println(F("Armed."));
}

void loop() {
  unsigned long now = millis();

  // PIR jumper note: this sketch assumes REPEAT-TRIGGER (H) mode, where
  // DOUT stays HIGH continuously while motion is sensed and the hold
  // timer keeps refreshing. In single-trigger (L) mode DOUT pulses then
  // goes low for the module's own dead time, so ALARM_HOLD_MS bridges
  // the pulses. Either works with the code below; repeat-trigger just
  // feels more responsive.
  if (digitalRead(PIR_PIN) == HIGH) {
    if (!alarmActive) {
      Serial.println(F("Motion! Alarm ON."));
      alarmActive = true;
    }
    lastMotionAt = now;     // refresh the hold window
  }

  // Rollover-safe: unsigned (now - lastMotionAt) is always the correct
  // elapsed time even when millis() wraps past 2^32.
  if (alarmActive && (now - lastMotionAt) >= ALARM_HOLD_MS) {
    Serial.println(F("All clear. Alarm OFF."));
    alarmActive = false;
    flag.write(90);         // park flag at centre
  }

  setLedBank(alarmActive);

  if (alarmActive) {
    if ((now - lastStep) >= SWEEP_STEP_MS) {
      lastStep = now;
      pos += dir;
      if (pos >= SWEEP_RIGHT) { pos = SWEEP_RIGHT; dir = -1; }
      if (pos <= SWEEP_LEFT)  { pos = SWEEP_LEFT;  dir =  1; }
      flag.write(pos);
    }
  }
}

