projects.code:
/*
 * AC Whisperer - DHT11 + KY-022 IR learn-and-replay AC controller
 *
 * Reads room temperature from a DHT11 every few seconds. When the room is
 * warmer than (target + 1.5C) it fires the saved COOL IR code at the AC.
 * When colder than (target - 1.5C) it fires WARM. In between it does
 * nothing. Codes are taught once by pressing TEACH and aiming your AC
 * remote at the KY-022 receiver. Codes survive a power cycle (stored in
 * Uno EEPROM).
 *
 * Hardware:
 *   D2 - KY-022 IR receiver signal
 *   D3 - IR LED through BC337 + 220R (MUST be pin 3 on AVR Uno - Timer2)
 *   D4 - DHT11 data
 *   D5 - TEACH button (INPUT_PULLUP, other leg to GND)
 *   D6 - UP   button (INPUT_PULLUP)
 *   D7 - DOWN button (INPUT_PULLUP)
 *   A4 - LCD I2C SDA
 *   A5 - LCD I2C SCL
 *
 * Libraries (install via Tools -> Manage Libraries):
 *   - IRremote               by shirriff / Armin Joachimsmeyer (v3 or v4)
 *   - DHT sensor library     by Adafruit  (+ Adafruit Unified Sensor)
 *   - LiquidCrystal I2C      by Frank de Brabander
 */

// IR_SEND_PIN must be defined BEFORE the IRremote include so the library
// uses the fast hardware path on Timer2 (pin 3 on AVR Uno).
#define IR_SEND_PIN 3
#include <IRremote.hpp>

#include <DHT.h>
#include <LiquidCrystal_I2C.h>
#include <EEPROM.h>

// ---------- Configuration ----------
const uint8_t  PIN_IR_RECV       = 2;
const uint8_t  PIN_DHT           = 4;
const uint8_t  PIN_BTN_TEACH     = 5;
const uint8_t  PIN_BTN_UP        = 6;
const uint8_t  PIN_BTN_DOWN      = 7;

const uint8_t  LCD_I2C_ADDR      = 0x27;      // try 0x3F if your LCD is dim/blank

const float    DEAD_BAND_C       = 1.5f;      // hysteresis around target
const uint16_t SAMPLE_INTERVAL_MS = 4000;     // how often to read DHT11
const uint32_t MIN_SEND_GAP_MS   = 60000UL;   // 1 minute between IR sends so the
                                              // AC compressor isn't hammered
const uint8_t  TARGET_TEMP_DEFAULT_C = 24;
const uint8_t  TARGET_TEMP_MIN_C     = 16;
const uint8_t  TARGET_TEMP_MAX_C     = 30;

// ---------- EEPROM layout ----------
// [0..1]  magic 'AC' to recognise valid saved data
// [2]     target temperature in degrees C
// [3..14] three IRCode blocks of 4 bytes each (protocol/bits/raw)
const uint16_t EE_MAGIC_ADDR  = 0;
const uint16_t EE_TARGET_ADDR = 2;
const uint16_t EE_CODES_ADDR  = 3;
const uint16_t EE_MAGIC       = 0x4143;       // 'A','C'

struct IRCode {
  uint8_t  protocol;     // decoded_type_t cast to uint8_t
  uint8_t  numberOfBits;
  uint32_t rawData;      // decoded primary data
};

enum SlotIndex : uint8_t { SLOT_COOL = 0, SLOT_OFF = 1, SLOT_WARM = 2, SLOT_COUNT = 3 };
const char* const SLOT_NAMES[SLOT_COUNT] = { "COOL", "OFF ", "WARM" };

IRCode   savedCodes[SLOT_COUNT] = {};
uint8_t  targetTempC            = TARGET_TEMP_DEFAULT_C;
uint32_t lastSampleMs           = 0;
uint32_t lastSendMs             = 0;
float    lastTempC              = NAN;
SlotIndex lastSentSlot          = SLOT_COUNT;  // SLOT_COUNT = "nothing yet"

DHT               dht(PIN_DHT, DHT11);
LiquidCrystal_I2C lcd(LCD_I2C_ADDR, 16, 2);

// ---------- EEPROM helpers ----------
void loadFromEeprom() {
  uint16_t magic;
  EEPROM.get(EE_MAGIC_ADDR, magic);
  if (magic != EE_MAGIC) {
    Serial.println(F("EEPROM blank - using defaults, no codes saved yet."));
    targetTempC = TARGET_TEMP_DEFAULT_C;
    for (uint8_t i = 0; i < SLOT_COUNT; i++) savedCodes[i] = IRCode{};
    return;
  }
  EEPROM.get(EE_TARGET_ADDR, targetTempC);
  for (uint8_t i = 0; i < SLOT_COUNT; i++) {
    EEPROM.get(EE_CODES_ADDR + i * sizeof(IRCode), savedCodes[i]);
  }
  Serial.println(F("EEPROM loaded."));
}

void saveTarget() {
  EEPROM.put(EE_TARGET_ADDR, targetTempC);
  uint16_t magic = EE_MAGIC;
  EEPROM.put(EE_MAGIC_ADDR, magic);
}

void saveCode(SlotIndex slot, const IRCode& code) {
  savedCodes[slot] = code;
  EEPROM.put(EE_CODES_ADDR + slot * sizeof(IRCode), code);
  uint16_t magic = EE_MAGIC;
  EEPROM.put(EE_MAGIC_ADDR, magic);
}

// ---------- Display ----------
void lcdShowStatus(const __FlashStringHelper* actionLine) {
  lcd.clear();
  lcd.setCursor(0, 0);
  lcd.print(F("Now "));
  if (isnan(lastTempC)) {
    lcd.print(F("--C"));
  } else {
    lcd.print((int)round(lastTempC));
    lcd.print((char)223);          // degree symbol
    lcd.print('C');
  }
  lcd.print(F(" Set "));
  lcd.print((int)targetTempC);
  lcd.print((char)223);
  lcd.print('C');

  lcd.setCursor(0, 1);
  lcd.print(F("AUTO "));
  lcd.print(actionLine);
}

void lcdShowTeachPrompt(SlotIndex slot) {
  lcd.clear();
  lcd.setCursor(0, 0);
  lcd.print(F("TEACH: aim AC"));
  lcd.setCursor(0, 1);
  lcd.print(F("remote, hit "));
  lcd.print(SLOT_NAMES[slot]);
}

void lcdShowTeachResult(SlotIndex slot, bool ok) {
  lcd.clear();
  lcd.setCursor(0, 0);
  lcd.print(SLOT_NAMES[slot]);
  lcd.print(F(": "));
  lcd.print(ok ? F("SAVED OK") : F("UNKNOWN"));
  lcd.setCursor(0, 1);
  lcd.print(ok ? F("Next slot...") : F("Try again..."));
}

// ---------- Buttons (active-low with INPUT_PULLUP, simple debounce) ----------
struct Button {
  uint8_t  pin;
  bool     lastReading;
  uint32_t lastChangeMs;
  bool     stableState;
};

Button btnTeach{PIN_BTN_TEACH, true, 0, true};
Button btnUp   {PIN_BTN_UP,    true, 0, true};
Button btnDown {PIN_BTN_DOWN,  true, 0, true};

bool buttonPressedEdge(Button& b) {
  bool reading = digitalRead(b.pin);
  if (reading != b.lastReading) {
    b.lastChangeMs = millis();
    b.lastReading  = reading;
  }
  if (millis() - b.lastChangeMs > 30) {
    if (reading != b.stableState) {
      b.stableState = reading;
      if (b.stableState == LOW) return true;   // newly pressed
    }
  }
  return false;
}

// ---------- IR receive (with timeout) ----------
bool waitForIrCode(IRCode& out, uint32_t timeoutMs) {
  uint32_t start = millis();
  while (millis() - start < timeoutMs) {
    if (IrReceiver.decode()) {
      uint32_t raw     = IrReceiver.decodedIRData.decodedRawData;
      bool     repeat  = IrReceiver.decodedIRData.flags & IRDATA_FLAGS_IS_REPEAT;
      uint8_t  proto   = (uint8_t)IrReceiver.decodedIRData.protocol;
      uint8_t  bits    = IrReceiver.decodedIRData.numberOfBits;
      IrReceiver.resume();
      if (!repeat && raw != 0) {
        out = IRCode{ proto, bits, raw };
        return true;
      }
    }
  }
  return false;
}

// ---------- IR send ----------
void sendSlot(SlotIndex slot) {
  IRCode c = savedCodes[slot];
  if (c.rawData == 0 || c.protocol == 0) {
    Serial.print(F("Slot ")); Serial.print(SLOT_NAMES[slot]);
    Serial.println(F(" is empty - press TEACH first."));
    return;
  }
  IRData send;
  send.protocol        = (decode_type_t)c.protocol;
  send.address         = 0;
  send.command         = 0;
  send.numberOfBits    = c.numberOfBits;
  send.flags           = 0;
  send.decodedRawData  = c.rawData;
  send.extra           = 0;
  IrSender.write(&send, 0);
  Serial.print(F("Sent ")); Serial.print(SLOT_NAMES[slot]);
  Serial.print(F(" proto=")); Serial.print(c.protocol);
  Serial.print(F(" bits=")); Serial.print(c.numberOfBits);
  Serial.print(F(" raw=0x")); Serial.println(c.rawData, HEX);
}

// ---------- Teach flow (blocking) ----------
void runTeachMode() {
  Serial.println(F("--- TEACH MODE ---"));
  for (uint8_t i = 0; i < SLOT_COUNT; i++) {
    SlotIndex slot = (SlotIndex)i;
    lcdShowTeachPrompt(slot);
    Serial.print(F("Aim remote and press "));
    Serial.println(SLOT_NAMES[slot]);

    IRCode got;
    bool ok = false;
    for (uint8_t attempt = 0; attempt < 3 && !ok; attempt++) {
      ok = waitForIrCode(got, 15000);
      if (!ok) {
        Serial.println(F("  no code in 15s, retrying..."));
        lcd.clear(); lcd.setCursor(0,0); lcd.print(F("Timeout - retry"));
        delay(800);
        lcdShowTeachPrompt(slot);
      }
    }
    if (ok) {
      saveCode(slot, got);
      lcdShowTeachResult(slot, true);
      Serial.print(F("  saved proto=")); Serial.print(got.protocol);
      Serial.print(F(" bits=")); Serial.print(got.numberOfBits);
      Serial.print(F(" raw=0x"));      Serial.println(got.rawData, HEX);
    } else {
      lcdShowTeachResult(slot, false);
      Serial.println(F("  giving up on this slot."));
    }
    delay(1500);
  }
  Serial.println(F("Teach mode done, returning to AUTO."));
}

// ---------- Setup / Loop ----------
void setup() {
  Serial.begin(115200);
  while (!Serial && millis() < 2000) { /* wait briefly for USB serial */ }

  pinMode(PIN_BTN_TEACH, INPUT_PULLUP);
  pinMode(PIN_BTN_UP,    INPUT_PULLUP);
  pinMode(PIN_BTN_DOWN,  INPUT_PULLUP);

  IrReceiver.begin(PIN_IR_RECV, ENABLE_LED_FEEDBACK);
  IrSender.begin(DISABLE_LED_FEEDBACK);

  dht.begin();
  lcd.init();
  lcd.backlight();

  loadFromEeprom();

  lcd.clear();
  lcd.setCursor(0, 0); lcd.print(F("AC Whisperer"));
  lcd.setCursor(0, 1); lcd.print(F("ready"));
  Serial.println(F("AC Whisperer ready"));
  delay(1200);

  lcdShowStatus(F("IDLE"));
}

void loop() {
  // ---- Buttons ----
  if (buttonPressedEdge(btnTeach)) {
    runTeachMode();
    lcdShowStatus(F("IDLE"));
  }
  if (buttonPressedEdge(btnUp)) {
    if (targetTempC < TARGET_TEMP_MAX_C) {
      targetTempC++;
      saveTarget();
      lcdShowStatus(F("IDLE"));
    }
  }
  if (buttonPressedEdge(btnDown)) {
    if (targetTempC > TARGET_TEMP_MIN_C) {
      targetTempC--;
      saveTarget();
      lcdShowStatus(F("IDLE"));
    }
  }

  // ---- Periodic temperature check ----
  uint32_t now = millis();
  if (now - lastSampleMs < SAMPLE_INTERVAL_MS) return;
  lastSampleMs = now;

  float t = dht.readTemperature();
  if (isnan(t)) {
    Serial.println(F("DHT11 read failed."));
    return;
  }
  lastTempC = t;
  Serial.print(F("temp=")); Serial.print(t, 1);
  Serial.print(F("C target=")); Serial.print((int)targetTempC); Serial.println(F("C"));

  bool gapOk = (lastSendMs == 0) || (now - lastSendMs > MIN_SEND_GAP_MS);

  if (t > targetTempC + DEAD_BAND_C && gapOk) {
    sendSlot(SLOT_COOL);
    lastSendMs = now;
    lastSentSlot = SLOT_COOL;
    lcdShowStatus(F("SENT COOL"));
  } else if (t < targetTempC - DEAD_BAND_C && gapOk) {
    sendSlot(SLOT_WARM);
    lastSendMs = now;
    lastSentSlot = SLOT_WARM;
    lcdShowStatus(F("SENT WARM"));
  } else {
    // Within dead-band, or send-gap not elapsed - just refresh the display.
    lcdShowStatus(lastSentSlot == SLOT_COOL ? F("COOLING  ")
                : lastSentSlot == SLOT_WARM ? F("WARMING  ")
                : F("IDLE     "));
  }
}

