projects.code:
// Two-Player Dual-Gang Score Knob -- "Sum-to-9" edition
// Board: Arduino Uno R3
// Display: 0.56" common-cathode 7-segment (1 digit), 8 segments wired directly to D2..D9 via 220R each.
// Knob: WH148 10K stereo (dual-gang) pot. ONE shaft, TWO wipers.
//        Gang A is wired the normal way (5V -> outer1, GND -> outer2). A0 reads 0..1023 as you turn.
//        Gang B is wired BACKWARDS (GND -> outer1, 5V -> outer2). A1 reads 1023..0 as you turn.
//        Result: P1 + P2 always equals 9 (one goes up, the other goes down on the same twist).
// Extras: Red 5mm LED on D11 lights up when EITHER player lands exactly on their secret target digit.
//         Push-button on D12 picks a new random target pair and clears the alert.
//
// What it does:
//   - Reads each pot gang, averages 8 samples to kill jitter, maps to a 0..9 score.
//   - Time-multiplexes ONE physical digit between Player 1 and Player 2:
//       * For SHOW_MS milliseconds we draw P1's score (decimal point OFF).
//       * For SHOW_MS milliseconds we draw P2's score (decimal point ON, like a name tag).
//   - At startup and on every press of the reset button, a new pair of target digits is rolled.
//     Because P1 + P2 = 9, the two targets also sum to 9 (e.g. P1 target = 3, P2 target = 6).
//   - Whoever twists the knob until THEIR shown digit matches THEIR target wins the round.
//     When either player is on their target, the red LED comes on. When both are on target
//     (which happens at exactly one shaft position), the LED flashes fast in celebration.

#include <Arduino.h>

// ---- Pin map (matches the wiring diagram) ----
const uint8_t SEG_PIN[8] = {
    2,  // a
    3,  // b
    4,  // c
    5,  // d
    6,  // e
    7,  // f
    8,  // g
    9   // dp
};
const uint8_t PIN_P1     = A0;   // Player 1 pot wiper (gang A, normal)
const uint8_t PIN_P2     = A1;   // Player 2 pot wiper (gang B, inverted)
const uint8_t PIN_BTN    = 12;   // new-round button (INPUT_PULLUP)
const uint8_t PIN_ALERT  = 11;   // on-target LED (NOT D13 - that's the onboard LED)

// ---- Tuning ----
const uint8_t  SAMPLES        = 8;     // analog reads to average per gang
const uint16_t SHOW_MS        = 500;   // how long each player's digit is displayed before swapping
const uint16_t WIN_FLASH_MS   = 100;   // fast-flash period when BOTH players are on target

// ---- 7-segment patterns for 0..9 ----
// Bit order: a=bit0, b=bit1, c=bit2, d=bit3, e=bit4, f=bit5, g=bit6, dp=bit7.
// To read a bit: take the pattern, shift it right by N places, then mask with 0x01.
// Example: pattern = 0b00111111 (digit 0). Bit 0 (segment a) = (0b00111111 >> 0) & 1 = 1 -> light it.
const uint8_t DIGIT[10] = {
    0b00111111, // 0
    0b00000110, // 1
    0b01011011, // 2
    0b01001111, // 3
    0b01100110, // 4
    0b01101101, // 5
    0b01111101, // 6
    0b00000111, // 7
    0b01111111, // 8
    0b01101111  // 9
};

// ---- State ----
uint8_t  targetP1      = 3;     // P1's secret target digit this round
uint8_t  targetP2      = 6;     // P2's secret target digit = 9 - targetP1
bool     showingP2     = false; // which player is on the display right now
uint32_t lastSwapMs    = 0;     // when did we last swap whose score is shown
uint32_t lastFlashMs   = 0;     // for the double-win celebratory flash
bool     flashState    = false;

// Drive the 8 segment pins from a single bit pattern (8 LEDs in one byte).
void writeSegments(uint8_t pattern) {
    for (uint8_t i = 0; i < 8; i++) {
        // Common cathode: write HIGH to light a segment.
        // (pattern >> i) shifts the bit we care about into position 0,
        // then & 0x01 keeps only that single bit -- 1 means "light it", 0 means "off".
        digitalWrite(SEG_PIN[i], (pattern >> i) & 0x01 ? HIGH : LOW);
    }
}

// Blank the display (all segments off).
void blankDisplay() {
    writeSegments(0);
}

// Light up the right segments for a single digit 0..9, with optional decimal point.
void showDigit(uint8_t value, bool dot) {
    if (value > 9) value = 9;
    uint8_t pattern = DIGIT[value];
    if (dot) pattern |= 0b10000000;
    writeSegments(pattern);
}

// Read a pot gang, average SAMPLES reads, and return a 0..9 score.
uint8_t readScore(uint8_t pin) {
    uint32_t sum = 0;
    for (uint8_t i = 0; i < SAMPLES; i++) {
        sum += analogRead(pin);
    }
    uint16_t avg = sum / SAMPLES;          // 0..1023
    int score = map(avg, 0, 1023, 0, 9);   // 0..9
    if (score < 0) score = 0;
    if (score > 9) score = 9;
    return (uint8_t)score;
}

// Roll a new target for P1 (1..8 so neither player gets a trivial 0 or 9 target).
// P2's target is forced to 9 - P1's target so the game is fair on a sum-to-9 knob.
void rollNewTargets() {
    targetP1 = (uint8_t)random(1, 9);   // 1..8 inclusive
    targetP2 = 9 - targetP1;
    Serial.print(F("New round! P1 target=")); Serial.print(targetP1);
    Serial.print(F("  P2 target=")); Serial.println(targetP2);
}

void setup() {
    Serial.begin(9600);
    Serial.println(F("Two-Player Dual-Gang Score Knob (sum-to-9): ready"));

    for (uint8_t i = 0; i < 8; i++) {
        pinMode(SEG_PIN[i], OUTPUT);
        digitalWrite(SEG_PIN[i], LOW);
    }
    pinMode(PIN_ALERT, OUTPUT);
    digitalWrite(PIN_ALERT, LOW);
    pinMode(PIN_BTN, INPUT_PULLUP);

    // Seed the random number generator from a floating analog pin (A2 is unused).
    randomSeed(analogRead(A2));
    rollNewTargets();

    lastSwapMs  = millis();
    lastFlashMs = millis();
}

void loop() {
    uint32_t now = millis();

    // ---- 1. New-round button: pick a fresh target pair ----
    if (digitalRead(PIN_BTN) == LOW) {
        delay(20); // tiny debounce
        if (digitalRead(PIN_BTN) == LOW) {
            rollNewTargets();
            digitalWrite(PIN_ALERT, LOW);
            // wait for release so we do not spam
            while (digitalRead(PIN_BTN) == LOW) delay(10);
            lastSwapMs = millis();
            return;
        }
    }

    // ---- 2. Read both scores ----
    uint8_t p1 = readScore(PIN_P1);
    uint8_t p2 = readScore(PIN_P2);

    // ---- 3. On-target alert ----
    bool p1OnTarget = (p1 == targetP1);
    bool p2OnTarget = (p2 == targetP2);

    if (p1OnTarget && p2OnTarget) {
        // Both players landed on their target at the same shaft angle.
        // Celebrate with a fast flash.
        if ((uint32_t)(now - lastFlashMs) >= WIN_FLASH_MS) {
            lastFlashMs = now;
            flashState  = !flashState;
            digitalWrite(PIN_ALERT, flashState ? HIGH : LOW);
        }
    } else if (p1OnTarget || p2OnTarget) {
        // One player is on their target -- steady on.
        digitalWrite(PIN_ALERT, HIGH);
    } else {
        digitalWrite(PIN_ALERT, LOW);
    }

    // ---- 4. Time-multiplex the single digit between the two players ----
    if ((uint32_t)(now - lastSwapMs) >= SHOW_MS) {
        showingP2  = !showingP2;
        lastSwapMs = now;
        Serial.print(F("P1=")); Serial.print(p1);
        Serial.print(F(" (target ")); Serial.print(targetP1); Serial.print(F(")"));
        Serial.print(F("  P2=")); Serial.print(p2);
        Serial.print(F(" (target ")); Serial.print(targetP2); Serial.print(F(")"));
        Serial.print(F("  showing="));
        Serial.println(showingP2 ? F("P2") : F("P1"));
    }

    if (showingP2) {
        showDigit(p2, true);   // dp ON = "this is Player 2"
    } else {
        showDigit(p1, false);  // dp OFF = "this is Player 1"
    }
}

