// Tasmota Plant Nightlight
// NodeMCU V3 (ESP8266) taps the standalone Soil Moisture Probe Meter's
// prong via a 1M pull-up divider on A0, and sends HTTP commands to a
// pre-flashed ESP-01S Tasmota relay to switch a 12V LED strip on when
// the soil gets dry. Two status LEDs (red = dry, green = wet) on the
// breadboard show the live decision.
//
// IMPORTANT about the soil meter: the meter is battery-powered and
// stands alone. We do NOT feed 3.3V into the meter. We only share the
// probe prong - one alligator lead from the prong goes to a 1M
// resistor pulled up to 3V3, and the junction connects to A0. Wetter
// soil = lower A0 reading; drier soil = higher A0 reading.
//
// Board: NodeMCU 1.0 (ESP-12E Module)
// Pins:  A0 = soil prong tap, D5 (GPIO14) = red LED, D6 (GPIO12) = green LED
//
// Before uploading: replace PASSWORD_HERE with your real WiFi password,
// and set TASMOTA_IP to the IP shown in your router's device list for
// the ESP-01S relay (e.g. 192.168.1.42).

#include <ESP8266WiFi.h>
#include <ESP8266HTTPClient.h>
#include <WiFiClient.h>

const char* WIFI_SSID     = "GeeFam";
const char* WIFI_PASSWORD = "PASSWORD_HERE";

// Set this to the IP your Tasmota relay receives from your router.
// You can find it in the Tasmota web UI or in your router's device list.
const char* TASMOTA_IP    = "192.168.1.42";

// If you turn on WebUI auth in Tasmota, fill these in and the URL
// builder below will append them. Leave blank for default open setup.
const char* TASMOTA_USER  = "";
const char* TASMOTA_PASS  = "";

const int PIN_SOIL  = A0;       // analog probe tap input
const int PIN_DRY   = 14;       // D5 -> red LED via 220R
const int PIN_WET   = 12;       // D6 -> green LED via 220R

// Tune these to YOUR pot AFTER wiring. Stick the probe in a glass of
// water and read the serial monitor to find WET_THRESHOLD (low number);
// let it dry out completely and read it again for DRY_THRESHOLD (high
// number). Remember: with our pull-up divider, WET = lower, DRY = higher.
// NodeMCU A0 range is 0..1023.
const int WET_THRESHOLD = 450;  // BELOW this counts as WET
const int DRY_THRESHOLD = 700;  // ABOVE this counts as DRY
// Between WET_THRESHOLD and DRY_THRESHOLD is the "tuning band" - the
// dashboard blinks both LEDs gently and the relay is not toggled, so
// borderline readings don't make the relay chatter back and forth.

const unsigned long SAMPLE_INTERVAL_MS = 5000UL;   // read soil every 5s
const unsigned long MIN_TOGGLE_GAP_MS  = 60000UL;  // don't flip relay more than once a minute

bool          relayOn        = false;
bool          relayStateKnown = false;
unsigned long lastSampleMs   = 0;
unsigned long lastToggleMs   = 0;

// Build a Tasmota /cm URL with optional auth.
String buildTasmotaUrl(const String& cmnd) {
  String url = String("http://") + TASMOTA_IP + "/cm?cmnd=" + cmnd;
  if (strlen(TASMOTA_USER) > 0) {
    url += "&user=";
    url += TASMOTA_USER;
    url += "&password=";
    url += TASMOTA_PASS;
  }
  return url;
}

void connectWiFi() {
  Serial.print("Connecting to ");
  Serial.println(WIFI_SSID);
  WiFi.mode(WIFI_STA);
  WiFi.begin(WIFI_SSID, WIFI_PASSWORD);
  unsigned long start = millis();
  while (WiFi.status() != WL_CONNECTED && millis() - start < 20000UL) {
    delay(250);
    Serial.print(".");
  }
  Serial.println();
  if (WiFi.status() == WL_CONNECTED) {
    Serial.print("WiFi up. IP: ");
    Serial.println(WiFi.localIP());
  } else {
    Serial.println("WiFi failed - will retry in loop.");
  }
}

// Fire a Tasmota command and return the raw JSON body (empty on failure).
String tasmotaGet(const String& cmnd) {
  String body = "";
  if (WiFi.status() != WL_CONNECTED) {
    Serial.println("No WiFi; skipping Tasmota command.");
    return body;
  }
  WiFiClient client;
  HTTPClient http;
  String url = buildTasmotaUrl(cmnd);
  Serial.print("GET ");
  Serial.println(url);
  if (!http.begin(client, url)) {
    Serial.println("http.begin failed");
    return body;
  }
  int code = http.GET();
  Serial.print("HTTP code: ");
  Serial.println(code);
  if (code == 200) {
    body = http.getString();
  } else if (code == 401) {
    Serial.println("Got 401 - Tasmota WebUI auth is enabled. Set TASMOTA_USER / TASMOTA_PASS.");
  }
  http.end();
  return body;
}

// Ask Tasmota what state the relay is actually in, so our local
// 'relayOn' flag matches reality after we boot.
bool queryRelayState() {
  String body = tasmotaGet("Power");
  if (body.length() == 0) {
    return false;
  }
  // Tasmota answers with JSON like {"POWER":"ON"} or {"POWER":"OFF"}.
  if (body.indexOf("\"ON\"") >= 0) {
    relayOn = true;
    relayStateKnown = true;
    Serial.println("Tasmota reports relay is currently ON.");
    return true;
  }
  if (body.indexOf("\"OFF\"") >= 0) {
    relayOn = false;
    relayStateKnown = true;
    Serial.println("Tasmota reports relay is currently OFF.");
    return true;
  }
  Serial.print("Could not parse Tasmota Power response: ");
  Serial.println(body);
  return false;
}

void setRelay(bool on) {
  String body = tasmotaGet(on ? "Power%20On" : "Power%20Off");
  if (body.length() > 0) {
    relayOn = on;
    relayStateKnown = true;
    lastToggleMs = millis();
    Serial.print("Relay -> ");
    Serial.println(on ? "ON" : "OFF");
  } else {
    Serial.println("Relay command failed.");
  }
}

void setup() {
  Serial.begin(115200);
  delay(200);
  Serial.println();
  Serial.println("Tasmota Plant Nightlight starting up.");

  pinMode(PIN_DRY, OUTPUT);
  pinMode(PIN_WET, OUTPUT);
  digitalWrite(PIN_DRY, LOW);
  digitalWrite(PIN_WET, LOW);

  connectWiFi();
  // Ask the relay what its real current state is, instead of assuming.
  if (!queryRelayState()) {
    Serial.println("Could not read relay state; will treat as unknown until first toggle.");
  }
}

void loop() {
  if (WiFi.status() != WL_CONNECTED) {
    connectWiFi();
    // After a reconnect, re-sync our idea of the relay state.
    queryRelayState();
  }

  unsigned long now = millis();
  if (now - lastSampleMs < SAMPLE_INTERVAL_MS) {
    return;
  }
  lastSampleMs = now;

  int raw = analogRead(PIN_SOIL);
  Serial.print("Soil raw: ");
  Serial.println(raw);

  // Update dashboard LEDs every sample.
  // WET = low reading, DRY = high reading (because of the pull-up divider).
  if (raw > DRY_THRESHOLD) {
    digitalWrite(PIN_DRY, HIGH);
    digitalWrite(PIN_WET, LOW);
  } else if (raw < WET_THRESHOLD) {
    digitalWrite(PIN_DRY, LOW);
    digitalWrite(PIN_WET, HIGH);
  } else {
    // Tuning band: between the two thresholds, blink both LEDs gently
    // out of phase so it's visually obvious we are NOT going to toggle
    // the relay on a borderline reading.
    digitalWrite(PIN_DRY, (now / 500) % 2);
    digitalWrite(PIN_WET, (now / 500 + 1) % 2);
  }

  // Only toggle the relay if enough time has passed, to avoid clicking
  // back and forth on a borderline reading.
  if (now - lastToggleMs < MIN_TOGGLE_GAP_MS) {
    return;
  }

  if (raw > DRY_THRESHOLD && (!relayOn || !relayStateKnown)) {
    Serial.println("Plant is DRY - turning nightlight ON.");
    setRelay(true);
  } else if (raw < WET_THRESHOLD && (relayOn || !relayStateKnown)) {
    Serial.println("Plant is WET - turning nightlight OFF.");
    setRelay(false);
  }
}

// Screw-Terminal Weather Card
// NodeMCU V3 + I/O Shield + GY-BMP280
// Reads pressure + temperature, serves a phone-friendly page,
// shows a barometer trend arrow based on the last 3 hours.

#include <ESP8266WiFi.h>
#include <ESP8266WebServer.h>
#include <Wire.h>
#include <Adafruit_BMP280.h>

// ---- WiFi ----
const char* WIFI_SSID = "GeeFam";
const char* WIFI_PASS = "PASSWORD_HERE";

// ---- I2C pins on NodeMCU V3 ----
// D1 = GPIO5 = SCL
// D2 = GPIO4 = SDA
const int PIN_SDA = 4;   // D2
const int PIN_SCL = 5;   // D1

Adafruit_BMP280 bmp;
ESP8266WebServer server(80);

// ---- Trend tracking ----
// We keep 12 samples spaced 15 minutes apart = 3 hours of history.
const int HIST_SLOTS = 12;
float pressureHist[HIST_SLOTS];
bool  histFilled[HIST_SLOTS];
int   histHead = 0;
unsigned long lastSampleMs = 0;
const unsigned long SAMPLE_INTERVAL_MS = 15UL * 60UL * 1000UL; // 15 min

// ---- Current readings ----
float currentTempC = 0.0;
float currentPresHpa = 0.0;

void recordSample(float hpa) {
  pressureHist[histHead] = hpa;
  histFilled[histHead] = true;
  histHead = (histHead + 1) % HIST_SLOTS;
}

// Returns trend: -1 falling, 0 steady, +1 rising
// Compares newest sample to oldest available.
int computeTrend() {
  // Find oldest filled slot (the one we are about to overwrite next)
  int oldestIdx = histHead;
  int newestIdx = (histHead - 1 + HIST_SLOTS) % HIST_SLOTS;
  if (!histFilled[oldestIdx] || !histFilled[newestIdx]) {
    return 0; // not enough history yet
  }
  float oldP = pressureHist[oldestIdx];
  float newP = pressureHist[newestIdx];
  float delta = newP - oldP;
  if (delta > 1.0) return 1;
  if (delta < -1.0) return -1;
  return 0;
}

String trendArrow(int t) {
  if (t > 0) return "&#9650;"; // up triangle
  if (t < 0) return "&#9660;"; // down triangle
  return "&#9654;";            // right triangle (steady)
}

String trendWord(int t) {
  if (t > 0) return "Rising";
  if (t < 0) return "Falling";
  return "Steady";
}

String trendStory(int t) {
  if (t > 0) return "Pressure is going up - usually means fair weather is on the way.";
  if (t < 0) return "Pressure is dropping - clouds or rain could be coming.";
  return "Pressure is holding steady - probably more of the same weather.";
}

void handleRoot() {
  int t = computeTrend();
  String arrow = trendArrow(t);
  String word  = trendWord(t);
  String story = trendStory(t);

  String html;
  html.reserve(1800);
  html += F("<!DOCTYPE html><html><head><meta charset='utf-8'>");
  html += F("<meta name='viewport' content='width=device-width,initial-scale=1'>");
  html += F("<meta http-equiv='refresh' content='30'>");
  html += F("<title>Weather Card</title>");
  html += F("<style>");
  html += F("body{font-family:system-ui,sans-serif;background:#0f172a;color:#f8fafc;margin:0;padding:16px;}");
  html += F(".card{max-width:420px;margin:0 auto;background:#1e293b;border-radius:16px;padding:24px;box-shadow:0 6px 24px rgba(0,0,0,.4);}");
  html += F("h1{margin:0 0 12px;font-size:1.4rem;color:#93c5fd;}");
  html += F(".big{font-size:3rem;font-weight:700;margin:8px 0;}");
  html += F(".lbl{color:#94a3b8;text-transform:uppercase;font-size:.75rem;letter-spacing:.08em;}");
  html += F(".row{display:flex;justify-content:space-between;margin:18px 0;}");
  html += F(".arrow{font-size:4rem;text-align:center;color:#fbbf24;}");
  html += F(".story{margin-top:14px;font-size:.95rem;line-height:1.4;color:#cbd5e1;}");
  html += F("</style></head><body><div class='card'>");
  html += F("<h1>Weather Card</h1>");
  html += F("<div class='row'><div><div class='lbl'>Temperature</div><div class='big'>");
  html += String(currentTempC, 1);
  html += F(" &deg;C</div></div></div>");
  html += F("<div class='row'><div><div class='lbl'>Pressure</div><div class='big'>");
  html += String(currentPresHpa, 1);
  html += F(" hPa</div></div></div>");
  html += F("<div class='arrow'>");
  html += arrow;
  html += F("</div><div style='text-align:center;font-weight:600;'>");
  html += word;
  html += F("</div><div class='story'>");
  html += story;
  html += F("</div></div></body></html>");

  server.send(200, "text/html", html);
}

void setup() {
  Serial.begin(115200);
  delay(100);
  Serial.println();
  Serial.println(F("Screw-Terminal Weather Card booting..."));

  // Clear history
  for (int i = 0; i < HIST_SLOTS; i++) {
    pressureHist[i] = 0.0;
    histFilled[i] = false;
  }

  Wire.begin(PIN_SDA, PIN_SCL);

  // Try the BMP280 at its two possible I2C addresses.
  // Most GY-BMP280 boards answer at 0x76, a few at 0x77.
  bool sensorFound = false;
  if (bmp.begin(0x76)) {
    sensorFound = true;
    Serial.println(F("BMP280 found at 0x76"));
  } else {
    if (bmp.begin(0x77)) {
      sensorFound = true;
      Serial.println(F("BMP280 found at 0x77"));
    }
  }
  if (!sensorFound) {
    Serial.println(F("BMP280 not found. Check wiring."));
    while (1) { delay(1000); }
  }

  bmp.setSampling(Adafruit_BMP280::MODE_NORMAL,
                  Adafruit_BMP280::SAMPLING_X2,
                  Adafruit_BMP280::SAMPLING_X16,
                  Adafruit_BMP280::FILTER_X16,
                  Adafruit_BMP280::STANDBY_MS_500);

  WiFi.mode(WIFI_STA);
  WiFi.begin(WIFI_SSID, WIFI_PASS);
  Serial.print(F("Connecting to WiFi"));
  unsigned long start = millis();
  while (WiFi.status() != WL_CONNECTED && millis() - start < 30000) {
    delay(400);
    Serial.print('.');
  }
  Serial.println();
  if (WiFi.status() == WL_CONNECTED) {
    Serial.print(F("IP: "));
    Serial.println(WiFi.localIP());
  } else {
    Serial.println(F("WiFi failed. Will keep trying."));
  }

  server.on("/", handleRoot);
  server.begin();
  Serial.println(F("HTTP server started on port 80"));

  // Take a first reading so the page has data immediately.
  currentTempC = bmp.readTemperature();
  currentPresHpa = bmp.readPressure() / 100.0F;
  recordSample(currentPresHpa);
  lastSampleMs = millis();
}

void loop() {
  server.handleClient();

  // Update current readings every 2 seconds
  static unsigned long lastReadMs = 0;
  if (millis() - lastReadMs > 2000) {
    currentTempC = bmp.readTemperature();
    currentPresHpa = bmp.readPressure() / 100.0F;
    lastReadMs = millis();
  }

  // Record a trend sample every 15 minutes
  if (millis() - lastSampleMs > SAMPLE_INTERVAL_MS) {
    recordSample(currentPresHpa);
    lastSampleMs = millis();
    Serial.print(F("Sample recorded: "));
    Serial.print(currentPresHpa, 1);
    Serial.println(F(" hPa"));
  }
}

