// Fog-the-Window Cloud Demo
// Arduino Uno reads DHT11 inside a glass jar, prints temp + humidity to a
// 1602 I2C LCD, and blinks a blue LED when the air is humid enough that fog
// WOULD form against the cold lid. The Peltier itself is switched by the
// W1209 thermostat in an independent loop -- the Uno never controls it.

#include <Wire.h>
#include <LiquidCrystal_I2C.h>
#include <DHT.h>

// ---- Pins ----
const uint8_t PIN_DHT     = 2;   // DHT11 data
const uint8_t PIN_FOG_LED = 8;   // Blue indicator LED via 220R

// ---- Hardware ----
#define DHT_TYPE DHT11
DHT dht(PIN_DHT, DHT_TYPE);
LiquidCrystal_I2C lcd(0x27, 16, 2); // change to 0x3F if your backpack uses it

// ---- Fog detection thresholds ----
// The Arduino cannot read the lid temperature -- the W1209 owns the NTC.
// We instead estimate the dew point from jar air temp and humidity using
// the Magnus approximation. With the W1209 setpoint at ~5-8C, fog WILL
// form against the lid whenever the air's dew point is well above that.
// We light the LED on dew point >= 10C AND humidity >= 70%.
const float FOG_DEWPOINT_C   = 10.0;
const float FOG_HUMIDITY_PCT = 70.0;

float dewPointC(float tempC, float humidityPct) {
  // Magnus formula constants
  const float a = 17.62;
  const float b = 243.12;
  float gamma = (a * tempC) / (b + tempC) + log(humidityPct / 100.0);
  return (b * gamma) / (a - gamma);
}

unsigned long lastRead  = 0;
unsigned long lastBlink = 0;
bool ledState = false;
bool fogLikely = false;

void setup() {
  Serial.begin(9600);
  Serial.println(F("Fog-the-Window Cloud Demo starting..."));

  pinMode(PIN_FOG_LED, OUTPUT);
  digitalWrite(PIN_FOG_LED, LOW);

  Wire.begin();
  lcd.init();
  lcd.backlight();
  lcd.setCursor(0, 0);
  lcd.print(F("Cloud Demo"));
  lcd.setCursor(0, 1);
  lcd.print(F("Warming up..."));

  dht.begin();
  delay(2000); // DHT11 needs a moment after power-on
}

void loop() {
  unsigned long now = millis();

  // DHT11 only updates ~once per second; read every 2s to be safe.
  if (now - lastRead >= 2000) {
    lastRead = now;

    float h = dht.readHumidity();
    float t = dht.readTemperature();

    if (isnan(h) || isnan(t)) {
      Serial.println(F("DHT11 read failed"));
      lcd.setCursor(0, 1);
      lcd.print(F("DHT11 error    "));
      return;
    }

    float dp = dewPointC(t, h);
    fogLikely = (dp >= FOG_DEWPOINT_C) && (h >= FOG_HUMIDITY_PCT);

    // ---- Serial ----
    Serial.print(F("T="));     Serial.print(t, 1);
    Serial.print(F("C  H="));  Serial.print(h, 0);
    Serial.print(F("%  Dew="));Serial.print(dp, 1);
    Serial.print(F("C  Fog="));Serial.println(fogLikely ? F("LIKELY") : F("no"));

    // ---- LCD ----
    lcd.setCursor(0, 0);
    lcd.print(F("T="));
    lcd.print(t, 1);
    lcd.print((char)223); // degree symbol
    lcd.print(F("C H="));
    lcd.print((int)h);
    lcd.print(F("%   "));

    lcd.setCursor(0, 1);
    lcd.print(F("Dew="));
    lcd.print(dp, 1);
    lcd.print((char)223);
    lcd.print(F("C "));
    lcd.print(fogLikely ? F("FOG!") : F("    "));
  }

  // ---- Fog LED ----
  if (fogLikely) {
    // Blink 2 Hz when the air is humid enough that fog would form on a cold lid
    if (now - lastBlink >= 250) {
      lastBlink = now;
      ledState = !ledState;
      digitalWrite(PIN_FOG_LED, ledState ? HIGH : LOW);
    }
  } else {
    if (ledState) {
      ledState = false;
      digitalWrite(PIN_FOG_LED, LOW);
    }
  }
}

