// Twin-Knob Web Mixer
// NodeMCU V3 (ESP8266) + WH148 stereo pot + 3 LEDs (R/G/B)
//
// Wiring (must match the diagram):
//   Left  pot gang: outer pins to 3V3 and GND, wiper -> A0 (analog brightness 0..1023)
//   Right pot gang: outer pins to 3V3 and GND, wiper -> D7 (digital: HIGH above ~1.4V)
//   LEDs (each via 220R to GND):
//     Red   anode -> D1
//     Green anode -> D2
//     Blue  anode -> D5   (NOT D3 - D3 is GPIO0, a boot-strap pin)
//
// Behaviour: the LEFT knob sets brightness. The RIGHT knob acts as a "next
// colour" trigger - every time you turn it past the middle of its travel
// the colour mode advances (Red -> Green -> Blue -> White -> Red ...).
// Turn it back below the middle, then forward again to step once more.

#include <ESP8266WiFi.h>
#include <ESP8266WebServer.h>

const char* WIFI_SSID = "GeeFam";
const char* WIFI_PASS = "PASSWORD_HERE";

// Pins (NodeMCU labels)
const int PIN_POT_L  = A0;   // left wiper, analog
const int PIN_POT_R  = D7;   // right wiper, digital threshold
const int PIN_LED_R  = D1;   // Red   LED, PWM
const int PIN_LED_G  = D2;   // Green LED, PWM
const int PIN_LED_B  = D5;   // Blue  LED, PWM (avoid D3 = GPIO0 boot pin)

ESP8266WebServer server(80);

// Latest sampled values (plain globals - no ISR touches them)
int     g_left    = 0;       // 0..1023 from A0
bool    g_rightHi = false;   // current digital state of right wiper
uint8_t g_mode    = 0;       // 0=Red, 1=Green, 2=Blue, 3=White

unsigned long lastModeChange = 0;
bool prevRightHi = false;

const char* MODE_NAMES[4] = {"Red", "Green", "Blue", "White"};

void applyOutputs() {
  // ESP8266 analogWrite is 0..1023 by default - matches A0 range directly.
  int bright = g_left;
  int r = 0, g = 0, b = 0;
  switch (g_mode) {
    case 0: r = bright; break;
    case 1: g = bright; break;
    case 2: b = bright; break;
    case 3: r = bright; g = bright; b = bright; break;
  }
  analogWrite(PIN_LED_R, r);
  analogWrite(PIN_LED_G, g);
  analogWrite(PIN_LED_B, b);
}

void sampleInputs() {
  g_left = analogRead(PIN_POT_L);
  bool nowHi = digitalRead(PIN_POT_R) == HIGH;

  // Rising-edge counter: each time the right wiper crosses HIGH (~1.4V),
  // bump the colour mode by one. 250 ms debounce keeps a jittery crossing
  // from skipping ahead.
  if (nowHi && !prevRightHi && (millis() - lastModeChange) > 250) {
    g_mode = (g_mode + 1) & 0x03;
    lastModeChange = millis();
  }
  prevRightHi = nowHi;
  g_rightHi = nowHi;
}

const char INDEX_HTML[] PROGMEM = R"HTML(
<!doctype html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Twin-Knob Web Mixer</title>
<style>
  body{font-family:system-ui,sans-serif;background:#0b1020;color:#e2e8f0;margin:0;padding:24px;}
  h1{font-size:20px;margin:0 0 16px;}
  .row{margin:12px 0;}
  .label{font-size:14px;color:#94a3b8;margin-bottom:6px;}
  .bar{height:28px;background:#1e293b;border-radius:8px;overflow:hidden;}
  .fill{height:100%;background:linear-gradient(90deg,#22d3ee,#a78bfa);width:0%;transition:width 80ms linear;}
  .swatch{height:80px;border-radius:12px;margin-top:8px;border:2px solid #334155;}
  .pill{display:inline-block;padding:4px 10px;border-radius:999px;background:#1e293b;font-size:12px;color:#cbd5e1;}
  .hint{font-size:12px;color:#64748b;margin-top:4px;}
</style></head>
<body>
  <h1>Twin-Knob Web Mixer</h1>
  <div class="row"><div class="label">Left knob - brightness <span class="pill" id="lv">0</span></div>
    <div class="bar"><div class="fill" id="lb"></div></div>
    <div class="hint">Smooth: follows the knob as you turn it.</div>
  </div>
  <div class="row"><div class="label">Right knob - colour step <span class="pill" id="rv">Red</span></div>
    <div class="bar"><div class="fill" id="rb"></div></div>
    <div class="hint">Steps: jumps to the next colour each time you turn past the middle.</div>
  </div>
  <div class="row"><div class="label">Live colour</div>
    <div class="swatch" id="sw"></div>
  </div>
<script>
const modes = ["Red","Green","Blue","White"];
async function tick(){
  try{
    const r = await fetch('/v',{cache:'no-store'});
    const j = await r.json();
    const pct = Math.round(j.left*100/1023);
    document.getElementById('lb').style.width = pct+'%';
    document.getElementById('lv').textContent = j.left;
    document.getElementById('rb').style.width = ((j.mode+1)*25)+'%';
    document.getElementById('rv').textContent = modes[j.mode];
    const c = j.color;
    document.getElementById('sw').style.background =
      'rgb('+c[0]+','+c[1]+','+c[2]+')';
  }catch(e){}
  setTimeout(tick,120);
}
tick();
</script></body></html>
)HTML";

void handleRoot() {
  server.send_P(200, "text/html", INDEX_HTML);
}

void handleValues() {
  int bright8 = map(g_left, 0, 1023, 0, 255);
  int rr = 0, gg = 0, bb = 0;
  switch (g_mode) {
    case 0: rr = bright8; break;
    case 1: gg = bright8; break;
    case 2: bb = bright8; break;
    case 3: rr = bright8; gg = bright8; bb = bright8; break;
  }
  String json = "{\"left\":";
  json += g_left;
  json += ",\"mode\":";
  json += g_mode;
  json += ",\"right\":";
  json += (g_rightHi ? 1 : 0);
  json += ",\"color\":[";
  json += rr; json += ","; json += gg; json += ","; json += bb;
  json += "]}";
  server.send(200, "application/json", json);
}

void setup() {
  Serial.begin(115200);
  delay(50);
  Serial.println();
  Serial.println("Twin-Knob Web Mixer starting...");

  pinMode(PIN_POT_R, INPUT);
  pinMode(PIN_LED_R, OUTPUT);
  pinMode(PIN_LED_G, OUTPUT);
  pinMode(PIN_LED_B, OUTPUT);
  analogWrite(PIN_LED_R, 0);
  analogWrite(PIN_LED_G, 0);
  analogWrite(PIN_LED_B, 0);

  WiFi.mode(WIFI_STA);
  WiFi.begin(WIFI_SSID, WIFI_PASS);
  Serial.print("Joining "); Serial.print(WIFI_SSID);
  unsigned long t0 = millis();
  while (WiFi.status() != WL_CONNECTED && millis() - t0 < 30000) {
    delay(300);
    Serial.print('.');
  }
  Serial.println();
  if (WiFi.status() == WL_CONNECTED) {
    Serial.print("IP: ");
    Serial.println(WiFi.localIP());
  } else {
    Serial.println("WiFi failed - check SSID/password.");
  }

  server.on("/", handleRoot);
  server.on("/v", handleValues);
  server.begin();
  Serial.println("Web server up on port 80");
}

void loop() {
  server.handleClient();
  sampleInputs();
  applyOutputs();
  delay(15);
}

