// VU Meter Stereo Volume Display
// Reads both gangs of a WH148 stereo pot and draws live L/R bar graphs
// on a 16x2 LCD with I2C backpack.
//
// Power: Uno is USB-powered from the laptop. The pot's outer pins and the
// LCD's VCC both come from the Uno's own 5V pin, so the ADC and the pot
// share the same supply (ratiometric reading - the most accurate way).

#include <Wire.h>
#include <LiquidCrystal_I2C.h>

// LCD at the common I2C address. If yours is 0x3F change this line.
LiquidCrystal_I2C lcd(0x27, 16, 2);

const uint8_t PIN_LEFT  = A0;   // WH148 wiper, left  gang
const uint8_t PIN_RIGHT = A1;   // WH148 wiper, right gang

// We use 13 of the 16 columns for the bar so columns 0..2 hold the label
// "L:" / "R:" and the bar starts at column 3.
const uint8_t BAR_START_COL = 3;
const uint8_t BAR_WIDTH     = 13;            // 13 character cells
const uint8_t BAR_PIXELS    = BAR_WIDTH * 5; // each cell is 5 px wide => 65 px

// Five pre-baked custom glyphs, one for each partial-cell fill level
// (1 pixel through 5 pixels). We load these into the LCD's custom-char
// slots 1..5. Slot 0 is intentionally left unused so we never call
// lcd.write(0) (some LiquidCrystal_I2C forks treat 0 as a string
// terminator and skip the write).
const byte BAR_GLYPHS[5][8] = {
  // 1 pixel filled (just the leftmost column of the 5-wide cell)
  { 0b00000, 0b10000, 0b10000, 0b10000, 0b10000, 0b10000, 0b10000, 0b00000 },
  // 2 pixels filled
  { 0b00000, 0b11000, 0b11000, 0b11000, 0b11000, 0b11000, 0b11000, 0b00000 },
  // 3 pixels filled
  { 0b00000, 0b11100, 0b11100, 0b11100, 0b11100, 0b11100, 0b11100, 0b00000 },
  // 4 pixels filled
  { 0b00000, 0b11110, 0b11110, 0b11110, 0b11110, 0b11110, 0b11110, 0b00000 },
  // 5 pixels filled (full cell)
  { 0b00000, 0b11111, 0b11111, 0b11111, 0b11111, 0b11111, 0b11111, 0b00000 },
};

void loadBarGlyphs() {
  // Slots 1..5 hold the partial-fill glyphs. Slot 0 is left untouched.
  for (uint8_t i = 0; i < 5; i++) {
    lcd.createChar(i + 1, (uint8_t *)BAR_GLYPHS[i]);
  }
}

void drawBar(uint8_t row, uint16_t analogValue) {
  // Map 0..1023 to 0..BAR_PIXELS pixels of bar length.
  uint16_t pixels = (uint32_t)analogValue * BAR_PIXELS / 1023;

  for (uint8_t col = 0; col < BAR_WIDTH; col++) {
    lcd.setCursor(BAR_START_COL + col, row);
    if (pixels >= 5) {
      lcd.write((uint8_t)5);     // fully filled cell (custom slot 5)
      pixels -= 5;
    } else if (pixels > 0) {
      lcd.write((uint8_t)pixels); // partial cell (custom slot 1..4)
      pixels = 0;
    } else {
      lcd.print(' ');             // empty cell - print a space, never write(0)
    }
  }
}

void setup() {
  Serial.begin(115200);
  Wire.begin();
  lcd.init();
  lcd.backlight();

  loadBarGlyphs();

  lcd.setCursor(0, 0); lcd.print("L:");
  lcd.setCursor(0, 1); lcd.print("R:");

  Serial.println(F("VU Meter Stereo Volume Display ready"));
}

void loop() {
  // A tiny moving-average filter so the bar does not jitter at rest.
  static uint16_t avgL = 0, avgR = 0;
  uint16_t rawL = analogRead(PIN_LEFT);
  uint16_t rawR = analogRead(PIN_RIGHT);
  avgL = (avgL * 3 + rawL) / 4;
  avgR = (avgR * 3 + rawR) / 4;

  drawBar(0, avgL);
  drawBar(1, avgR);

  // Print the raw channel values + the gap, so the "channel mismatch"
  // lesson is also visible on the serial monitor.
  Serial.print(F("L=")); Serial.print(rawL);
  Serial.print(F("  R=")); Serial.print(rawR);
  Serial.print(F("  diff=")); Serial.println((int)rawL - (int)rawR);

  delay(50);   // ~20 frames per second
}

