// Tempo + Pitch Twin-Track Visual Sequencer
//
// One WH148 stereo pot shaft controls TWO things at once:
//   Gang A (A0) -> tempo       (60..300 BPM)
//   Gang B (A1) -> brightness  (PWM 20..255 on the red LED)
//
// A red LED on a PWM pin flashes on every beat at the brightness the
// second gang asks for. A single-digit 7-segment display counts beats
// 0..7 then loops back to 0.
//
// Common-cathode 7-segment wiring (segments a..g + dp via 220R each):
//   a -> D2,  b -> D3,  c -> D4,  d -> D5,
//   e -> D6,  f -> D7,  g -> D8,  dp -> D9
//   COM (both common-cathode pins) -> GND
//
// LED: D10 -> 220R -> LED anode (+), LED cathode (-) -> GND.
// Pot: outer pins -> 5V and GND. Wiper A -> A0, wiper B -> A1.

const uint8_t PIN_TEMPO_POT      = A0;
const uint8_t PIN_BRIGHTNESS_POT = A1;
const uint8_t PIN_LED            = 10; // PWM-capable on Uno

// 7-segment segment pins, in order a,b,c,d,e,f,g,dp
const uint8_t SEG_PINS[8] = {2, 3, 4, 5, 6, 7, 8, 9};

// Segment bit patterns for digits 0..9 (a=bit0 .. g=bit6, dp=bit7).
// 1 = segment ON (for common cathode: HIGH turns segment on).
const uint8_t DIGITS[10] = {
  0b00111111, // 0
  0b00000110, // 1
  0b01011011, // 2
  0b01001111, // 3
  0b01100110, // 4
  0b01101101, // 5
  0b01111101, // 6
  0b00000111, // 7
  0b01111111, // 8
  0b01101111  // 9
};

unsigned long lastBeatMs = 0;
unsigned long ledOffAtMs = 0;
bool ledOn = false;
uint8_t beatCount = 0;

void showDigit(uint8_t d) {
  if (d > 9) d = 0;
  uint8_t pattern = DIGITS[d];
  for (uint8_t i = 0; i < 8; i++) {
    digitalWrite(SEG_PINS[i], (pattern >> i) & 0x01 ? HIGH : LOW);
  }
}

void blankDigit() {
  for (uint8_t i = 0; i < 8; i++) {
    digitalWrite(SEG_PINS[i], LOW);
  }
}

// Map 0..1023 -> 60..300 BPM
int readTempoBpm() {
  int raw = analogRead(PIN_TEMPO_POT);
  return map(raw, 0, 1023, 60, 300);
}

// Map 0..1023 -> 20..255 PWM (keep a visible minimum brightness)
int readBrightnessPwm() {
  int raw = analogRead(PIN_BRIGHTNESS_POT);
  return map(raw, 0, 1023, 20, 255);
}

void setup() {
  for (uint8_t i = 0; i < 8; i++) {
    pinMode(SEG_PINS[i], OUTPUT);
    digitalWrite(SEG_PINS[i], LOW);
  }
  pinMode(PIN_LED, OUTPUT);
  analogWrite(PIN_LED, 0);
  // Analog input pins default to high-impedance input on the Uno,
  // so no pinMode() call is needed for A0/A1.

  Serial.begin(9600);
  Serial.println(F("Tempo+Brightness Twin-Track Visual Sequencer"));
  showDigit(0);
  lastBeatMs = millis();
}

void loop() {
  int bpm        = readTempoBpm();
  int brightness = readBrightnessPwm();

  // Period between beats (ms) for current BPM
  unsigned long beatPeriod = 60000UL / (unsigned long)bpm;

  unsigned long now = millis();

  // Time for a new beat?
  if (now - lastBeatMs >= beatPeriod) {
    lastBeatMs = now;

    // Flash length is ~1/4 of the beat, clamped to 30..200 ms
    unsigned long flashMs = beatPeriod / 4;
    if (flashMs < 30)  flashMs = 30;
    if (flashMs > 200) flashMs = 200;

    analogWrite(PIN_LED, brightness);
    ledOn = true;
    ledOffAtMs = now + flashMs;

    beatCount = (beatCount + 1) % 8; // 0..7 then loop
    showDigit(beatCount);

    Serial.print(F("BPM=")); Serial.print(bpm);
    Serial.print(F("  bright=")); Serial.print(brightness);
    Serial.print(F("  beat=")); Serial.println(beatCount);
  }

  // Turn the LED off when the flash duration is up
  if (ledOn && (long)(now - ledOffAtMs) >= 0) {
    analogWrite(PIN_LED, 0);
    ledOn = false;
  }
}

