/*
  Two-Room Doorbell Pair - ESP-NOW
  --------------------------------
  This file contains BOTH sketches in one place. Pick one to flash to each
  ESP-01S by changing the ROLE define below.

      #define ROLE_SENDER     -> Front-door unit with the push button
      #define ROLE_RECEIVER   -> Other-room unit with the LED + Tasmota relay

  -----------------------------------------------------------------------
  IMPORTANT: ESP-01S boot-strap pins
  -----------------------------------------------------------------------
  At the instant of power-up, BEFORE setup() ever runs, the ESP8266 ROM
  samples GPIO0, GPIO2, RST and CH_PD to decide how to boot. If any of
  them are at the wrong level the chip will not start. So:

    GPIO0  must be HIGH at boot  -> 10k pull-up to 3V3
    RST    must be HIGH at boot  -> 10k pull-up to 3V3
    CH_PD  must be HIGH at boot  -> 10k pull-up to 3V3
    GPIO2  must be HIGH at boot  -> 10k pull-up to 3V3 (on BOTH boards)

  That last one is the one beginners miss. We use GPIO2 as the button
  input on the sender and as the LED driver on the receiver, but on BOTH
  boards GPIO2 needs an external pull-up so it reads HIGH while the chip
  is booting. INPUT_PULLUP / pinMode() do not help here because they only
  switch on AFTER setup() runs - too late.

  -----------------------------------------------------------------------
  Wiring (sender, bare ESP-01S)
  -----------------------------------------------------------------------
      GPIO2  -> push button -> GND
      GPIO2  -> 10k pull-up to 3V3   (boot-strap, MUST be present)
      GPIO0  -> 10k pull-up to 3V3
      RST    -> 10k pull-up to 3V3
      CH_PD  -> 10k pull-up to 3V3
      VCC    -> 3V3 rail from MB102  (NEVER 5V!)
      GND    -> GND

      WARNING: do NOT power up the board while holding the button down.
      Holding the button grounds GPIO2 and the chip will refuse to boot.

  -----------------------------------------------------------------------
  Wiring (receiver, ESP-01S Tasmota relay board)
  -----------------------------------------------------------------------
      Board takes 5V on its screw terminals (MB102 5V rail).
      The on-board ESP-01S drives GPIO0 to toggle the relay coil.
      The LED is wired ACTIVE-LOW so GPIO2 can stay HIGH at boot:

        3V3 rail -> 220 ohm -> LED anode -> LED cathode -> GPIO2

      When GPIO2 is HIGH (boot default + idle): no current flows, LED off.
      When GPIO2 is driven LOW: current flows from 3V3 through the LED to
      GPIO2 (which is now a 0V sink), LED lights up.

      Relay COM + NO terminals switch the 5V buzzer. The Tasmota relay is
      rated for LOW-VOLTAGE DC ONLY (buzzer, LED strip, small DC fan).
      NEVER mains voltage on this board.

  -----------------------------------------------------------------------
  Tasmota ESP-01S relay board polarity
  -----------------------------------------------------------------------
  On the common Tasmota-flashed ESP-01S relay carrier, GPIO0 drives the
  relay coil ACTIVE-LOW (coil energized when GPIO0 == LOW, contacts
  closed -> buzzer ON). The defines below match that. If your board
  turns out to be active-HIGH (rare), flip RELAY_ACTIVE_LOW to 0.

  -----------------------------------------------------------------------
  MAC pairing
  -----------------------------------------------------------------------
  Flash the RECEIVER first, open Serial Monitor at 115200 baud, copy the
  printed MAC, paste it into the RECEIVER_MAC array below, then flash the
  SENDER. The default value below is all zeros so the sketch will refuse
  to send until you have done the pairing step. (Broadcast fallback was
  removed because the ESP-NOW send-callback status is unreliable for
  broadcast frames on the ESP8266 SDK.)

  -----------------------------------------------------------------------
  Cosmetic note: ROM bootloader chatter on GPIO2
  -----------------------------------------------------------------------
  At every power-up the ESP8266 ROM bootloader prints a short banner on
  GPIO2 at 74880 baud before our sketch takes over. You may see the
  receiver LED twitch for a fraction of a second at boot. This is normal
  and harmless.
*/

// ----- PICK ONE ROLE BEFORE FLASHING -----
#define ROLE_SENDER
//#define ROLE_RECEIVER
// -----------------------------------------

#include <ESP8266WiFi.h>
#include <espnow.h>

// Polarity of the Tasmota ESP-01S relay carrier (1 = active-LOW = common).
#define RELAY_ACTIVE_LOW 1

// Receiver MAC - REPLACE these zeros with the MAC printed by the receiver
// on first boot. The sender refuses to send while this is all zeros.
uint8_t RECEIVER_MAC[6] = { 0x00, 0x00, 0x00, 0x00, 0x00, 0x00 };

// Tiny message format - one byte saying "ring!"
typedef struct DoorbellMessage {
  uint8_t  ring;       // 1 = ring now
  uint16_t pressCount; // optional: how many presses since power-up
} DoorbellMessage;

DoorbellMessage outgoing;
DoorbellMessage incoming;

static bool macIsZero(const uint8_t *mac) {
  for (int i = 0; i < 6; i++) if (mac[i] != 0) return false;
  return true;
}

// ===================== SENDER =====================
#ifdef ROLE_SENDER

const int BUTTON_PIN = 2;   // GPIO2 -> push button -> GND, with external 10k to 3V3
uint16_t pressCounter = 0;
unsigned long lastPressMs = 0;
const unsigned long DEBOUNCE_MS = 300;

void onSent(uint8_t *mac, uint8_t status) {
  Serial.print("Send status: ");
  Serial.println(status == 0 ? "OK" : "FAIL");
}

void setup() {
  Serial.begin(115200);
  delay(200);
  Serial.println();
  Serial.println("Doorbell SENDER booting...");

  // External 10k pull-up handles the boot-strap; INPUT here keeps the pin
  // clean and avoids fighting the external resistor.
  pinMode(BUTTON_PIN, INPUT);

  WiFi.mode(WIFI_STA);
  Serial.print("Sender MAC: ");
  Serial.println(WiFi.macAddress());

  if (macIsZero(RECEIVER_MAC)) {
    Serial.println("RECEIVER_MAC is all zeros - paste the receiver's MAC");
    Serial.println("into RECEIVER_MAC and re-flash. Halting.");
    while (true) { delay(1000); }
  }

  if (esp_now_init() != 0) {
    Serial.println("ESP-NOW init failed - rebooting");
    delay(2000);
    ESP.restart();
  }

  esp_now_set_self_role(ESP_NOW_ROLE_CONTROLLER);
  esp_now_register_send_cb(onSent);
  esp_now_add_peer(RECEIVER_MAC, ESP_NOW_ROLE_SLAVE, 1, NULL, 0);

  Serial.println("Sender ready. Press the button to ring.");
}

void loop() {
  // Active-low button: LOW means pressed
  if (digitalRead(BUTTON_PIN) == LOW) {
    unsigned long now = millis();
    if (now - lastPressMs > DEBOUNCE_MS) {
      lastPressMs = now;
      pressCounter++;
      outgoing.ring = 1;
      outgoing.pressCount = pressCounter;
      Serial.print("DING! Press #");
      Serial.println(pressCounter);
      esp_now_send(RECEIVER_MAC, (uint8_t *)&outgoing, sizeof(outgoing));
    }
  }
  delay(10);
}
#endif

// ===================== RECEIVER =====================
#ifdef ROLE_RECEIVER

const int LED_PIN   = 2;    // GPIO2: 3V3 -> 220 ohm -> LED -> GPIO2 (active-LOW)
const int RELAY_PIN = 0;    // GPIO0: drives the on-board Tasmota relay coil

unsigned long ringUntilMs = 0;
const unsigned long RING_DURATION_MS = 1500;

// Helper to drive the relay and the LED in a polarity-aware way so the
// sketch reads naturally ("relayOn(true)" = buzzer should sound).
static inline void relayOn(bool on) {
  if (RELAY_ACTIVE_LOW) digitalWrite(RELAY_PIN, on ? LOW : HIGH);
  else                  digitalWrite(RELAY_PIN, on ? HIGH : LOW);
}
static inline void ledOn(bool on) {
  // LED is active-LOW (anode tied to 3V3 through 220 ohm, cathode to GPIO2)
  digitalWrite(LED_PIN, on ? LOW : HIGH);
}

void onReceive(uint8_t *mac, uint8_t *data, uint8_t len) {
  if (len < (int)sizeof(DoorbellMessage)) return;
  memcpy(&incoming, data, sizeof(incoming));
  if (incoming.ring == 1) {
    Serial.print("Got ring #");
    Serial.println(incoming.pressCount);
    ringUntilMs = millis() + RING_DURATION_MS;
  }
}

void setup() {
  // IMPORTANT: set the idle (off) levels on RELAY_PIN and LED_PIN BEFORE
  // switching them to OUTPUT, so we never pulse the relay on for a frame
  // while the chip is booting.
  digitalWrite(RELAY_PIN, RELAY_ACTIVE_LOW ? HIGH : LOW); // relay OFF
  digitalWrite(LED_PIN,   HIGH);                          // LED OFF
  pinMode(RELAY_PIN, OUTPUT);
  pinMode(LED_PIN,   OUTPUT);

  Serial.begin(115200);
  delay(200);
  Serial.println();
  Serial.println("Doorbell RECEIVER booting...");

  WiFi.mode(WIFI_STA);
  Serial.print("Receiver MAC (paste this into the sender sketch): ");
  Serial.println(WiFi.macAddress());

  if (esp_now_init() != 0) {
    Serial.println("ESP-NOW init failed - rebooting");
    delay(2000);
    ESP.restart();
  }

  esp_now_set_self_role(ESP_NOW_ROLE_SLAVE);
  esp_now_register_recv_cb(onReceive);

  Serial.println("Receiver ready. Waiting for a ring...");
}

void loop() {
  unsigned long now = millis();
  if (now < ringUntilMs) {
    // Buzzer ON + LED blinking fast while we are inside the ring window
    relayOn(true);
    ledOn(((now / 100) % 2) == 0);
  } else {
    relayOn(false);
    ledOn(false);
  }
  delay(5);
}
#endif

