// Glovebox Climate Dash
// NodeMCU V3 (ESP8266) + DHT11 + BMP280 + 0.96" SSD1306 OLED
// Reads cabin temperature, humidity, and barometric pressure and
// shows them on the OLED. Powered from a 12V car socket via a
// 6-24V to 5V USB buck converter.
//
// Pin map (matches the wiring diagram):
//   D1 (GPIO5)  -> I2C SCL  (shared by BMP280 and OLED)
//   D2 (GPIO4)  -> I2C SDA  (shared by BMP280 and OLED)
//   D3 (GPIO0)  -> DHT11 DATA  (NOT D4 - D4/GPIO2 is the on-board LED
//                               and a boot-strap pin; we keep it free.)
//
// Note: DHT11 is powered from the 3V3 rail (not 5V) so its data line
// idles at 3.3V - safe for the ESP8266's 3.3V-only GPIOs.

#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>
#include <Adafruit_BMP280.h>
#include <DHT.h>

// ---------- Pins ----------
#define DHT_PIN     0     // D3 on NodeMCU V3 = GPIO0
#define DHT_TYPE    DHT11

// ---------- I2C addresses ----------
#define OLED_ADDR_A 0x3C
#define OLED_ADDR_B 0x3D
#define BMP_ADDR_A  0x76
#define BMP_ADDR_B  0x77

// ---------- OLED geometry ----------
#define SCREEN_W 128
#define SCREEN_H 64
#define OLED_RESET -1

Adafruit_SSD1306 display(SCREEN_W, SCREEN_H, &Wire, OLED_RESET);
Adafruit_BMP280 bmp;
DHT dht(DHT_PIN, DHT_TYPE);

// Trip min/max so the screen tells a story over time.
float tMin = 9999.0, tMax = -9999.0;
float pMin = 9999.0, pMax = -9999.0;

unsigned long lastRead = 0;
const unsigned long READ_INTERVAL_MS = 1500;

// ---------- helpers ----------
bool initOLED() {
  if (display.begin(SSD1306_SWITCHCAPVCC, OLED_ADDR_A)) return true;
  if (display.begin(SSD1306_SWITCHCAPVCC, OLED_ADDR_B)) return true;
  return false;
}

bool initBMP() {
  if (bmp.begin(BMP_ADDR_A)) return true;
  if (bmp.begin(BMP_ADDR_B)) return true;
  return false;
}

void splash(const char *line1, const char *line2) {
  display.clearDisplay();
  display.setTextSize(1);
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(0, 0);
  display.println(line1);
  display.println(line2);
  display.display();
}

void setup() {
  Serial.begin(115200);
  delay(50);
  Serial.println();
  Serial.println("Glovebox Climate Dash starting...");

  Wire.begin();        // default SDA=GPIO4 (D2), SCL=GPIO5 (D1) on NodeMCU
  dht.begin();

  if (!initOLED()) {
    Serial.println("OLED not found at 0x3C or 0x3D - check wiring.");
    // We can still run without the screen but there is no point - stop here.
    while (true) delay(1000);
  }
  splash("Climate Dash", "booting...");
  delay(800);

  if (!initBMP()) {
    Serial.println("BMP280 not found at 0x76 or 0x77.");
    splash("BMP280 missing", "check wiring");
    while (true) delay(1000);
  }

  // Standard "weather monitoring" config for the BMP280.
  bmp.setSampling(Adafruit_BMP280::MODE_NORMAL,
                  Adafruit_BMP280::SAMPLING_X2,
                  Adafruit_BMP280::SAMPLING_X16,
                  Adafruit_BMP280::FILTER_X16,
                  Adafruit_BMP280::STANDBY_MS_500);

  splash("Ready!", "Drive safe.");
  delay(800);
}

void loop() {
  unsigned long now = millis();
  if (now - lastRead < READ_INTERVAL_MS) {
    return;
  }
  lastRead = now;

  // ---------- Read sensors ----------
  float tempDHT = dht.readTemperature();   // deg C
  float humidity = dht.readHumidity();     // %
  float tempBMP  = bmp.readTemperature();  // deg C (for cross-check)
  float pressure = bmp.readPressure() / 100.0;  // Pa -> hPa
  float altitude = bmp.readAltitude(1013.25);   // m above sea-level std

  // Use BMP temperature if DHT failed (DHT11 is finicky).
  float tempShown = (isnan(tempDHT)) ? tempBMP : tempDHT;

  // ---------- Update trip min/max ----------
  if (!isnan(tempShown)) {
    if (tempShown < tMin) tMin = tempShown;
    if (tempShown > tMax) tMax = tempShown;
  }
  if (pressure > 300 && pressure < 1100) {  // sanity window
    if (pressure < pMin) pMin = pressure;
    if (pressure > pMax) pMax = pressure;
  }

  // ---------- Serial debug ----------
  Serial.print("T="); Serial.print(tempShown, 1);
  Serial.print("C  H="); Serial.print(humidity, 0);
  Serial.print("%  P="); Serial.print(pressure, 1);
  Serial.print("hPa  alt="); Serial.print(altitude, 0);
  Serial.println("m");

  // ---------- Draw OLED ----------
  display.clearDisplay();
  display.setTextColor(SSD1306_WHITE);

  // Header
  display.setTextSize(1);
  display.setCursor(0, 0);
  display.print("CLIMATE DASH");
  display.drawLine(0, 9, SCREEN_W - 1, 9, SSD1306_WHITE);

  // Big temperature
  display.setTextSize(2);
  display.setCursor(0, 14);
  if (isnan(tempShown)) {
    display.print("--.- C");
  } else {
    display.print(tempShown, 1);
    display.print((char)247);  // degree symbol on the SSD1306 font
    display.print("C");
  }

  // Humidity line
  display.setTextSize(1);
  display.setCursor(0, 34);
  display.print("Humidity: ");
  if (isnan(humidity)) {
    display.print("--");
  } else {
    display.print(humidity, 0);
  }
  display.print("%");

  // Pressure on its own line
  display.setCursor(0, 44);
  display.print("Press: ");
  display.print(pressure, 1);
  display.print(" hPa");

  // Bottom line: compact "A:NNNm H:NN L:NN" so 3-digit altitudes fit in 128 px.
  display.setCursor(0, 54);
  display.print("A:");
  display.print(altitude, 0);
  display.print("m H:");
  display.print(tMax, 0);
  display.print(" L:");
  display.print(tMin, 0);

  display.display();
}

