// Paired Touch Lamps - Long-Distance High-Five
// Same sketch flashed to both ESP-01S nodes.
// Before flashing each board, set MY_ROLE below (ROLE_A or ROLE_B).
// mDNS handles peer discovery - no need to re-flash with IP addresses!

#include <ESP8266WiFi.h>
#include <ESP8266WebServer.h>
#include <ESP8266HTTPClient.h>
#include <ESP8266mDNS.h>
#include <WiFiClient.h>

// ---------- CONFIGURE PER BOARD ----------
#define ROLE_A 1
#define ROLE_B 2
#define MY_ROLE ROLE_A          // flip to ROLE_B for the second lamp, then re-flash

const char* WIFI_SSID = "GeeFam";
const char* WIFI_PASS = "PASSWORD_HERE";
// -----------------------------------------

// Pins (ESP-01S has very few)
// LED is wired ACTIVE-LOW: 3.3V -> 220R -> LED anode -> LED cathode -> GPIO2
// That keeps GPIO2 HIGH at boot (required for the ESP-01S boot-strap).
// LOW = lamp ON, HIGH = lamp OFF.
const uint8_t PIN_LED    = 2;   // GPIO2, active-LOW
const uint8_t PIN_BUTTON = 0;   // GPIO0, button to GND, 10K pull-up to 3.3V
                                // (same pull-up keeps GPIO0 HIGH at boot for run mode)

const unsigned long GLOW_MS = 5000;   // how long the OTHER lamp glows
const unsigned long DEBOUNCE_MS = 50;

ESP8266WebServer server(80);

unsigned long glowUntil = 0;
int lastButtonReading = HIGH;
int stableButtonState = HIGH;
unsigned long lastButtonChangeMs = 0;
bool buttonHandled = false;

const char* peerHost() {
  // I ping the OTHER lamp's hostname, not my own.
  return (MY_ROLE == ROLE_A) ? "lampb.local" : "lampa.local";
}

const char* myName() {
  return (MY_ROLE == ROLE_A) ? "Lamp A" : "Lamp B";
}

const char* myHostname() {
  return (MY_ROLE == ROLE_A) ? "lampa" : "lampb";
}

void lampOn() {
  digitalWrite(PIN_LED, LOW);   // active-LOW: LOW = ON
}

void lampOff() {
  digitalWrite(PIN_LED, HIGH);  // active-LOW: HIGH = OFF
}

void handleGlow() {
  glowUntil = millis() + GLOW_MS;
  lampOn();
  server.send(200, "text/plain", "ok");
  Serial.println("Got /glow from peer - glowing now");
}

void handleRoot() {
  String body = String(myName()) + " is online. IP=" + WiFi.localIP().toString()
              + " host=" + String(myHostname()) + ".local";
  server.send(200, "text/plain", body);
}

void connectWifi() {
  Serial.print("Connecting to ");
  Serial.println(WIFI_SSID);
  WiFi.mode(WIFI_STA);
  WiFi.hostname(myHostname());
  WiFi.begin(WIFI_SSID, WIFI_PASS);
  unsigned long start = millis();
  while (WiFi.status() != WL_CONNECTED && millis() - start < 30000) {
    delay(500);
    Serial.print(".");
  }
  Serial.println();
  if (WiFi.status() == WL_CONNECTED) {
    Serial.print(myName());
    Serial.print(" booted, IP = ");
    Serial.println(WiFi.localIP());
  } else {
    Serial.println("WiFi failed - check SSID/password and that the network is 2.4GHz");
  }
}

void pingPeer() {
  if (WiFi.status() != WL_CONNECTED) return;
  WiFiClient client;
  HTTPClient http;
  String url = String("http://") + peerHost() + "/glow";
  Serial.print("Touching peer: ");
  Serial.println(url);
  // Short timeout so we do not block server.handleClient() too long
  // if the peer is offline or busy. 1.5 seconds is plenty on a LAN.
  http.setTimeout(1500);
  if (http.begin(client, url)) {
    int code = http.GET();
    Serial.print("peer responded: ");
    Serial.println(code);
    http.end();
  } else {
    Serial.println("http.begin failed");
  }
}

void setup() {
  Serial.begin(115200);
  delay(200);
  Serial.println();
  Serial.print("Booting ");
  Serial.println(myName());

  // LED: drive HIGH (OFF) before anything else so the boot pulse is invisible.
  pinMode(PIN_LED, OUTPUT);
  lampOff();

  // Button on GPIO0 - external 10K pull-up to 3.3V handles both the
  // boot-strap (must read HIGH at power-on for normal run mode) and the
  // input pull-up at runtime.
  pinMode(PIN_BUTTON, INPUT);

  connectWifi();

  // mDNS so each lamp can find the other as lampa.local / lampb.local
  // with no hand-coded IP addresses.
  if (MDNS.begin(myHostname())) {
    Serial.print("mDNS started as ");
    Serial.print(myHostname());
    Serial.println(".local");
  } else {
    Serial.println("mDNS failed to start");
  }

  server.on("/", handleRoot);
  server.on("/glow", handleGlow);
  server.begin();
  Serial.println("HTTP server started on port 80");
}

void loop() {
  MDNS.update();
  server.handleClient();

  // --- button: debounce + single-shot per press ---
  int reading = digitalRead(PIN_BUTTON);
  if (reading != lastButtonReading) {
    lastButtonChangeMs = millis();
    lastButtonReading = reading;
  }
  if (millis() - lastButtonChangeMs > DEBOUNCE_MS) {
    if (reading != stableButtonState) {
      stableButtonState = reading;
      if (stableButtonState == LOW && !buttonHandled) {
        buttonHandled = true;
        Serial.println("Button pressed - ping peer");
        pingPeer();
      }
      if (stableButtonState == HIGH) {
        buttonHandled = false;
      }
    }
  }

  // --- glow timer ---
  if (glowUntil != 0 && (long)(millis() - glowUntil) >= 0) {
    lampOff();
    glowUntil = 0;
    Serial.println("Glow finished");
  }
}

