// =====================================================================
// Pan-and-Tilt Joystick Cam - CONTROLLER sketch
// =====================================================================
// Target board: ESP32 NodeMCU-32S (select "ESP32 Dev Module" in IDE)
//
// Reads the WH148 dual-gang pot on TWO real ADC pins (GPIO34, GPIO35 -
// both are input-only, ideal for ADC) and drives two SG90 servos on
// GPIO13 (pan) and GPIO12 (tilt). Also serves a tiny status page and
// advertises itself as http://panctl.local/ over mDNS so you don't
// have to hunt for its IP address.
//
// The ESP32-CAM streamer is a SEPARATE board running the stock
// Arduino IDE example: File > Examples > ESP32 > Camera > CameraWebServer
// with CAMERA_MODEL_AI_THINKER selected and SSID/password edited.
// We do not include the camera code in this file - the stock example
// is shorter, smarter (handles PSRAM detection automatically) and
// official.
// =====================================================================

#include <WiFi.h>
#include <WebServer.h>
#include <ESPmDNS.h>
#include <ESP32Servo.h>

const char* WIFI_SSID = "GeeFam";
const char* WIFI_PASS = "PASSWORD_HERE";

// ----- Pin map (matches wiring diagram) -----
const int PIN_POT_PAN_WIPER  = 34;   // ADC1_CH6, input-only
const int PIN_POT_TILT_WIPER = 35;   // ADC1_CH7, input-only
const int PIN_SERVO_PAN      = 13;
const int PIN_SERVO_TILT     = 12;

// ----- ADC characteristics -----
// ESP32 ADC is 12-bit (0..4095) when configured at default 11dB.
// Both pot gangs are wired with top -> 3.3V and bottom -> GND
// so the wiper sweeps 0..3.3V across the full pot rotation.
const int ADC_MIN = 0;
const int ADC_MAX = 4095;

// ----- Servo travel limits (keep off the hard stops) -----
const int SERVO_MIN_DEG = 10;
const int SERVO_MAX_DEG = 170;

Servo servoPan;
Servo servoTilt;
WebServer server(80);

int panAngle  = 90;
int tiltAngle = 90;
String camIp  = "";    // last known camera IP (settable via /register?ip=...)

int rawToAngle(int raw) {
  int a = map(raw, ADC_MIN, ADC_MAX, SERVO_MIN_DEG, SERVO_MAX_DEG);
  if (a < SERVO_MIN_DEG) a = SERVO_MIN_DEG;
  if (a > SERVO_MAX_DEG) a = SERVO_MAX_DEG;
  return a;
}

void handleStatus() {
  String s = "{\"pan\":";
  s += panAngle;
  s += ",\"tilt\":";
  s += tiltAngle;
  s += ",\"cam_ip\":\"";
  s += camIp;
  s += "\"}";
  server.send(200, "application/json", s);
}

void handleRegister() {
  // The ESP32-CAM (or you, manually from a browser) can hit
  //   http://panctl.local/register?ip=192.168.x.y
  // so the controller page knows where the stream lives.
  if (server.hasArg("ip")) {
    camIp = server.arg("ip");
    server.send(200, "text/plain", "registered");
  } else {
    server.send(400, "text/plain", "missing ip");
  }
}

void handleRoot() {
  String camLink = camIp.length()
    ? ("<p><a href=\"http://" + camIp + "/\">Open camera stream</a></p>")
    : "<p><em>Camera IP not registered yet. Grab it from the CAM's Serial Monitor and visit <code>/register?ip=...</code>.</em></p>";

  String html =
    "<!doctype html><html><head><title>Pan/Tilt</title>"
    "<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">"
    "</head><body style=\"font-family:sans-serif\">"
    "<h2>Pan/Tilt Controller</h2>"
    "<p>Pan: " + String(panAngle) + " deg</p>"
    "<p>Tilt: " + String(tiltAngle) + " deg</p>"
    + camLink +
    "<p>Move the joystick to aim.</p>"
    "</body></html>";
  server.send(200, "text/html", html);
}

void setup() {
  Serial.begin(115200);
  delay(200);
  Serial.println();
  Serial.println("Pan/Tilt controller booting");

  // ADC pins on GPIO34/35 are input-only - no pinMode needed for read,
  // but we make it explicit.
  pinMode(PIN_POT_PAN_WIPER,  INPUT);
  pinMode(PIN_POT_TILT_WIPER, INPUT);

  // ESP32Servo allocates timers itself - just attach.
  servoPan.attach(PIN_SERVO_PAN);
  servoTilt.attach(PIN_SERVO_TILT);
  servoPan.write(panAngle);
  servoTilt.write(tiltAngle);

  WiFi.mode(WIFI_STA);
  WiFi.begin(WIFI_SSID, WIFI_PASS);
  Serial.print("WiFi connecting");
  unsigned long t0 = millis();
  while (WiFi.status() != WL_CONNECTED && millis() - t0 < 20000) {
    delay(300);
    Serial.print(".");
  }
  Serial.println();
  if (WiFi.status() == WL_CONNECTED) {
    Serial.print("Controller IP: ");
    Serial.println(WiFi.localIP());
    if (MDNS.begin("panctl")) {
      Serial.println("mDNS: http://panctl.local/");
    } else {
      Serial.println("mDNS start failed - use the IP above");
    }
  } else {
    Serial.println("WiFi failed - pot still works locally");
  }

  server.on("/", handleRoot);
  server.on("/status", handleStatus);
  server.on("/register", handleRegister);
  server.begin();
}

void loop() {
  server.handleClient();

  int rawPan  = analogRead(PIN_POT_PAN_WIPER);
  int rawTilt = analogRead(PIN_POT_TILT_WIPER);

  int targetPan  = rawToAngle(rawPan);
  int targetTilt = rawToAngle(rawTilt);

  // Small deadband so the servos don't jitter on ADC noise.
  if (abs(targetPan - panAngle) > 1) {
    panAngle = targetPan;
    servoPan.write(panAngle);
  }
  if (abs(targetTilt - tiltAngle) > 1) {
    tiltAngle = targetTilt;
    servoTilt.write(tiltAngle);
  }

  delay(20);
}

// =====================================================================
// CAMERA sketch - NOT in this file.
// Use Arduino IDE: File > Examples > ESP32 > Camera > CameraWebServer
//
// In that example:
//   1) Uncomment   #define CAMERA_MODEL_AI_THINKER
//   2) Comment out the other CAMERA_MODEL_* defines
//   3) Set       const char* ssid     = "GeeFam";
//                const char* password = "PASSWORD_HERE";
//   4) Select board "AI Thinker ESP32-CAM", port = MB programmer's COM
//   5) Upload (hold IO0 if your MB base needs it)
//   6) Open Serial Monitor at 115200, note the Camera IP
//   7) Optional: from a browser, visit
//        http://panctl.local/register?ip=<that-camera-ip>
//      so the controller page links to the stream automatically.
// =====================================================================

