// Cat-Bowl Watcher
// ESP32-CAM (AI Thinker) + ESP-01S Tasmota Relay over WiFi.
//
// Boots, joins WiFi, starts a tiny web server on port 80:
//   GET /        -> HTML page with the live MJPEG stream and a DISPENSE button
//   GET /stream  -> multipart MJPEG video stream (the live view)
//   GET /snap    -> a single JPEG frame
//   GET /dispense -> sends an HTTP GET to the Tasmota relay to TOGGLE its output
//
// The relay is pre-flashed with Tasmota; we just hit its HTTP command endpoint.
// Tasmota docs: http://<RELAY_IP>/cm?cmnd=POWER%20TOGGLE  toggles relay 1.
//
// Board:    AI Thinker ESP32-CAM
// Partition: Huge APP (3MB No OTA / 1MB SPIFFS)
// Upload:   115200 baud is fine, 921600 if your USB cable is good

#include <WiFi.h>
#include <WebServer.h>
#include <HTTPClient.h>
#include "esp_camera.h"

// ---- WiFi ----
const char* WIFI_SSID     = "GeeFam";
const char* WIFI_PASSWORD = "PASSWORD_HERE";

// ---- Tasmota relay address ----
// Set this to whatever IP your ESP-01S Relay grabbed on first boot.
// Find it in your router's DHCP list or via the Tasmota app.
const char* RELAY_IP      = "192.168.1.50";

// ---- AI Thinker ESP32-CAM pin map (do not edit) ----
#define PWDN_GPIO_NUM     32
#define RESET_GPIO_NUM    -1
#define XCLK_GPIO_NUM      0
#define SIOD_GPIO_NUM     26
#define SIOC_GPIO_NUM     27
#define Y9_GPIO_NUM       35
#define Y8_GPIO_NUM       34
#define Y7_GPIO_NUM       39
#define Y6_GPIO_NUM       36
#define Y5_GPIO_NUM       21
#define Y4_GPIO_NUM       19
#define Y3_GPIO_NUM       18
#define Y2_GPIO_NUM        5
#define VSYNC_GPIO_NUM    25
#define HREF_GPIO_NUM     23
#define PCLK_GPIO_NUM     22

WebServer server(80);

// MJPEG multipart boundary
static const char* STREAM_BOUNDARY = "--cbwframe";
static const char* STREAM_CT       = "multipart/x-mixed-replace;boundary=cbwframe";

void startCamera() {
  camera_config_t config;
  config.ledc_channel = LEDC_CHANNEL_0;
  config.ledc_timer   = LEDC_TIMER_0;
  config.pin_d0       = Y2_GPIO_NUM;
  config.pin_d1       = Y3_GPIO_NUM;
  config.pin_d2       = Y4_GPIO_NUM;
  config.pin_d3       = Y5_GPIO_NUM;
  config.pin_d4       = Y6_GPIO_NUM;
  config.pin_d5       = Y7_GPIO_NUM;
  config.pin_d6       = Y8_GPIO_NUM;
  config.pin_d7       = Y9_GPIO_NUM;
  config.pin_xclk     = XCLK_GPIO_NUM;
  config.pin_pclk     = PCLK_GPIO_NUM;
  config.pin_vsync    = VSYNC_GPIO_NUM;
  config.pin_href     = HREF_GPIO_NUM;
  config.pin_sccb_sda = SIOD_GPIO_NUM;
  config.pin_sccb_scl = SIOC_GPIO_NUM;
  config.pin_pwdn     = PWDN_GPIO_NUM;
  config.pin_reset    = RESET_GPIO_NUM;
  config.xclk_freq_hz = 20000000;
  config.pixel_format = PIXFORMAT_JPEG;

  if (psramFound()) {
    config.frame_size   = FRAMESIZE_VGA;     // 640x480
    config.jpeg_quality = 12;                // 0 best ... 63 worst
    config.fb_count     = 2;
    config.grab_mode    = CAMERA_GRAB_LATEST;
    config.fb_location  = CAMERA_FB_IN_PSRAM;
  } else {
    config.frame_size   = FRAMESIZE_QVGA;    // 320x240 fallback
    config.jpeg_quality = 15;
    config.fb_count     = 1;
    config.grab_mode    = CAMERA_GRAB_WHEN_EMPTY;
    config.fb_location  = CAMERA_FB_IN_DRAM;
  }

  esp_err_t err = esp_camera_init(&config);
  if (err != ESP_OK) {
    Serial.printf("Camera init failed 0x%x - check power and partition scheme.\n", err);
    while (true) { delay(1000); }
  }

  // Some OV2640 modules ship mirrored or upside-down. Flip these to taste.
  sensor_t* s = esp_camera_sensor_get();
  if (s) {
    s->set_vflip(s, 1);
    s->set_hmirror(s, 0);
    s->set_brightness(s, 0);
    s->set_saturation(s, 0);
  }
}

// ----- Web page -----
String renderPage() {
  String html;
  html.reserve(2000);
  html += F("<!doctype html><html><head><meta charset='utf-8'>"
           "<meta name='viewport' content='width=device-width,initial-scale=1'>"
           "<title>Cat-Bowl Watcher</title><style>"
           "body{font-family:system-ui,sans-serif;background:#0f172a;color:#f8fafc;"
           "display:flex;flex-direction:column;align-items:center;margin:0;padding:1rem;}"
           "h1{margin:0.25rem 0;font-size:1.5rem;}"
           "img{width:100%;max-width:640px;border-radius:12px;"
           "box-shadow:0 8px 24px rgba(0,0,0,0.5);background:#000;}"
           "a.btn{display:flex;align-items:center;justify-content:center;"
           "width:80vw;max-width:420px;height:90px;border-radius:14px;"
           "background:#10b981;color:#fff;font-size:1.5rem;font-weight:700;"
           "text-decoration:none;margin-top:1.25rem;"
           "box-shadow:0 6px 20px rgba(16,185,129,0.45);}"
           "a.btn:active{transform:scale(0.97);background:#059669;}"
           ".tip{opacity:0.65;margin-top:1rem;font-size:0.85rem;text-align:center;max-width:420px;}"
           "</style></head><body>"
           "<h1>Cat-Bowl Watcher</h1>"
           "<img src='/stream' alt='Live bowl view'>"
           "<a class='btn' href='/dispense'>DISPENSE TREAT</a>"
           "<p class='tip'>Tap the button to click the relay across the room. "
           "Watch the red LED on the dispenser light up.</p>"
           "</body></html>");
  return html;
}

void handleRoot() {
  server.send(200, "text/html", renderPage());
}

// ----- Single JPEG snapshot -----
void handleSnap() {
  camera_fb_t* fb = esp_camera_fb_get();
  if (!fb) {
    server.send(500, "text/plain", "Camera capture failed");
    return;
  }
  server.sendHeader("Content-Disposition", "inline; filename=snap.jpg");
  server.send_P(200, "image/jpeg", (const char*)fb->buf, fb->len);
  esp_camera_fb_return(fb);
}

// ----- MJPEG stream -----
void handleStream() {
  WiFiClient client = server.client();
  if (!client) return;

  String head = "HTTP/1.1 200 OK\r\n";
  head += "Content-Type: ";
  head += STREAM_CT;
  head += "\r\nCache-Control: no-store\r\n";
  head += "Connection: close\r\n\r\n";
  client.print(head);

  while (client.connected()) {
    camera_fb_t* fb = esp_camera_fb_get();
    if (!fb) {
      Serial.println("Frame grab failed");
      break;
    }

    String part = "";
    part += STREAM_BOUNDARY;
    part += "\r\nContent-Type: image/jpeg\r\nContent-Length: ";
    part += fb->len;
    part += "\r\n\r\n";
    client.print(part);
    client.write(fb->buf, fb->len);
    client.print("\r\n");

    esp_camera_fb_return(fb);

    // Cap at ~20 fps so the chip does not overheat or stall WiFi
    delay(50);

    if (!client.connected()) break;
  }
}

// ----- Fire the Tasmota relay -----
bool fireRelayToggle() {
  if (WiFi.status() != WL_CONNECTED) return false;
  HTTPClient http;
  String url = "http://";
  url += RELAY_IP;
  url += "/cm?cmnd=POWER%20TOGGLE";
  Serial.print("Calling relay: ");
  Serial.println(url);
  http.setConnectTimeout(2000);
  http.begin(url);
  int code = http.GET();
  http.end();
  Serial.printf("Relay response: %d\n", code);
  return code > 0 && code < 400;
}

void handleDispense() {
  bool ok = fireRelayToggle();
  // Redirect back to the page so the user sees the live stream again
  server.sendHeader("Location", "/");
  server.send(303);
  Serial.println(ok ? "Treat dispensed (relay toggled)." : "Relay call failed.");
}

void setup() {
  Serial.begin(115200);
  delay(200);
  Serial.println();
  Serial.println("Cat-Bowl Watcher booting...");

  startCamera();
  Serial.println("Camera ready");

  WiFi.mode(WIFI_STA);
  WiFi.begin(WIFI_SSID, WIFI_PASSWORD);
  Serial.print("Joining WiFi ");
  Serial.print(WIFI_SSID);
  unsigned long start = millis();
  while (WiFi.status() != WL_CONNECTED && millis() - start < 20000) {
    delay(400);
    Serial.print(".");
  }
  Serial.println();

  if (WiFi.status() != WL_CONNECTED) {
    Serial.println("WiFi join failed - rebooting in 5s.");
    delay(5000);
    ESP.restart();
  }

  Serial.print("Open this on your phone: http://");
  Serial.println(WiFi.localIP());

  server.on("/",         HTTP_GET, handleRoot);
  server.on("/stream",   HTTP_GET, handleStream);
  server.on("/snap",     HTTP_GET, handleSnap);
  server.on("/dispense", HTTP_GET, handleDispense);
  server.begin();
  Serial.println("Web server started on port 80.");
}

void loop() {
  server.handleClient();

  // Auto-reconnect if WiFi drops
  static unsigned long lastCheck = 0;
  if (millis() - lastCheck > 10000) {
    lastCheck = millis();
    if (WiFi.status() != WL_CONNECTED) {
      Serial.println("WiFi lost, reconnecting...");
      WiFi.reconnect();
    }
  }
}

