projects.code:
// Front-Porch Critter Cam
// ESP32-CAM (AI-Thinker) + HC-SR501 PIR + status LED.
// Snaps a JPEG on every PIR trigger, holds the last N in RAM,
// serves a simple gallery over WiFi.

#include "esp_camera.h"
#include <WiFi.h>
#include <WebServer.h>

// ---- WiFi ----
const char* WIFI_SSID = "GeeFam";
const char* WIFI_PASS = "PASSWORD_HERE";

// ---- Pins ----
// PIR on GPIO13: broken out to the side header on the AI-Thinker.
// External status LED on GPIO14: also broken out, general-purpose,
// and (unlike GPIO12) NOT a critical strapping pin, so we can safely
// drive it high or low at boot.
// NOTE: GPIO33 / GPIO32 are NOT on the side header of the AI-Thinker
// ESP32-CAM (GPIO33 drives the on-board red LED via a hidden SMT trace).
// Do not try to wire to them from the breadboard.
#define PIR_PIN     13
#define STATUS_LED  14   // external LED, wired anode->220R->GPIO14, cathode->GND => ACTIVE-HIGH

// ---- AI-Thinker ESP32-CAM camera pinout ----
#define PWDN_GPIO_NUM     32
#define RESET_GPIO_NUM    -1
#define XCLK_GPIO_NUM      0
#define SIOD_GPIO_NUM     26
#define SIOC_GPIO_NUM     27
#define Y9_GPIO_NUM       35
#define Y8_GPIO_NUM       34
#define Y7_GPIO_NUM       39
#define Y6_GPIO_NUM       36
#define Y5_GPIO_NUM       21
#define Y4_GPIO_NUM       19
#define Y3_GPIO_NUM       18
#define Y2_GPIO_NUM        5
#define VSYNC_GPIO_NUM    25
#define HREF_GPIO_NUM     23
#define PCLK_GPIO_NUM     22

// ---- Photo ring buffer ----
#define MAX_PHOTOS 8
struct Photo {
  uint8_t* buf;
  size_t   len;
  uint32_t when_ms;
};
Photo photos[MAX_PHOTOS];
int   photo_count = 0;   // total taken since boot
int   ring_head   = 0;   // next slot to overwrite

// ---- State ----
WebServer server(80);
unsigned long boot_ms = 0;
unsigned long last_trigger_ms = 0;
const unsigned long PIR_WARMUP_MS       = 60000; // ignore first 60s
const unsigned long TRIGGER_COOLDOWN_MS = 3000;  // min gap between photos

// External LED is wired anode-to-pin, cathode-to-GND through 220R,
// so it is ACTIVE-HIGH: HIGH = on, LOW = off.
void ledOn()  { digitalWrite(STATUS_LED, HIGH); }
void ledOff() { digitalWrite(STATUS_LED, LOW);  }

void blinkLed(int times) {
  for (int i = 0; i < times; i++) {
    ledOn();
    delay(80);
    ledOff();
    delay(120);
  }
}

bool initCamera() {
  camera_config_t config;
  config.ledc_channel = LEDC_CHANNEL_0;
  config.ledc_timer   = LEDC_TIMER_0;
  config.pin_d0 = Y2_GPIO_NUM;
  config.pin_d1 = Y3_GPIO_NUM;
  config.pin_d2 = Y4_GPIO_NUM;
  config.pin_d3 = Y5_GPIO_NUM;
  config.pin_d4 = Y6_GPIO_NUM;
  config.pin_d5 = Y7_GPIO_NUM;
  config.pin_d6 = Y8_GPIO_NUM;
  config.pin_d7 = Y9_GPIO_NUM;
  config.pin_xclk  = XCLK_GPIO_NUM;
  config.pin_pclk  = PCLK_GPIO_NUM;
  config.pin_vsync = VSYNC_GPIO_NUM;
  config.pin_href  = HREF_GPIO_NUM;
  config.pin_sccb_sda = SIOD_GPIO_NUM;
  config.pin_sccb_scl = SIOC_GPIO_NUM;
  config.pin_pwdn  = PWDN_GPIO_NUM;
  config.pin_reset = RESET_GPIO_NUM;
  config.xclk_freq_hz = 20000000;
  config.pixel_format = PIXFORMAT_JPEG;
  config.frame_size   = FRAMESIZE_SVGA; // 800x600 - kid-friendly file size
  config.jpeg_quality = 12;             // lower = better quality
  config.fb_count     = 2;
  config.fb_location  = CAMERA_FB_IN_PSRAM;
  config.grab_mode    = CAMERA_GRAB_LATEST;

  if (!psramFound()) {
    config.frame_size = FRAMESIZE_VGA;
    config.fb_location = CAMERA_FB_IN_DRAM;
    config.fb_count = 1;
  }

  esp_err_t err = esp_camera_init(&config);
  if (err != ESP_OK) {
    Serial.printf("Camera init failed 0x%x\n", err);
    return false;
  }
  return true;
}

void takePhoto() {
  camera_fb_t* fb = esp_camera_fb_get();
  if (!fb) {
    Serial.println("Frame grab failed");
    return;
  }

  // free old slot
  Photo& slot = photos[ring_head];
  if (slot.buf) {
    free(slot.buf);
    slot.buf = nullptr;
  }

  slot.buf = (uint8_t*) malloc(fb->len);
  if (!slot.buf) {
    Serial.println("malloc failed");
    esp_camera_fb_return(fb);
    return;
  }
  memcpy(slot.buf, fb->buf, fb->len);
  slot.len = fb->len;
  slot.when_ms = millis() - boot_ms;
  esp_camera_fb_return(fb);

  photo_count++;
  ring_head = (ring_head + 1) % MAX_PHOTOS;
  Serial.printf("Photo #%d, %u bytes\n", photo_count, (unsigned)slot.len);
  blinkLed(1);
}

void handleRoot() {
  String html = "<!doctype html><html><head><meta charset='utf-8'>";
  html += "<meta name='viewport' content='width=device-width,initial-scale=1'>";
  html += "<title>Critter Cam</title>";
  html += "<style>body{font-family:sans-serif;background:#111;color:#eee;margin:0;padding:1em}";
  html += "h1{font-size:1.4em}a{color:#7df}img{max-width:100%;border-radius:6px}";
  html += ".item{margin-bottom:1.5em;padding:0.5em;background:#222;border-radius:6px}</style></head><body>";
  html += "<h1>Front-Porch Critter Cam</h1>";
  html += "<p>Total triggers since boot: <b>" + String(photo_count) + "</b></p>";

  int shown = (photo_count < MAX_PHOTOS) ? photo_count : MAX_PHOTOS;
  // newest first
  for (int i = 0; i < shown; i++) {
    int idx = (ring_head - 1 - i + MAX_PHOTOS) % MAX_PHOTOS;
    if (!photos[idx].buf) continue;
    unsigned long secs = photos[idx].when_ms / 1000;
    html += "<div class='item'><div>" + String(secs) + "s after boot</div>";
    html += "<img src='/photo?i=" + String(idx) + "'></div>";
  }
  html += "</body></html>";
  server.send(200, "text/html", html);
}

void handlePhoto() {
  if (!server.hasArg("i")) {
    server.send(400, "text/plain", "missing i");
    return;
  }
  int idx = server.arg("i").toInt();
  if (idx < 0 || idx >= MAX_PHOTOS || !photos[idx].buf) {
    server.send(404, "text/plain", "no photo");
    return;
  }
  // Stream the JPEG without building a giant String temporary.
  server.setContentLength(photos[idx].len);
  server.sendHeader("Content-Type", "image/jpeg");
  server.sendHeader("Cache-Control", "no-store");
  server.send(200, "image/jpeg", "");
  server.client().write(photos[idx].buf, photos[idx].len);
}

void setup() {
  Serial.begin(115200);
  delay(200);
  Serial.println("\nFront-Porch Critter Cam booting");

  pinMode(STATUS_LED, OUTPUT);
  ledOff(); // start with the external LED off (active-high wiring)
  pinMode(PIR_PIN, INPUT);

  for (int i = 0; i < MAX_PHOTOS; i++) {
    photos[i].buf = nullptr;
    photos[i].len = 0;
    photos[i].when_ms = 0;
  }

  if (!initCamera()) {
    Serial.println("Camera init failed, halting");
    while (true) {
      blinkLed(3);
      delay(1000);
    }
  }
  Serial.println("Camera ready");

  WiFi.mode(WIFI_STA);
  WiFi.begin(WIFI_SSID, WIFI_PASS);
  Serial.print("WiFi ");
  unsigned long t0 = millis();
  while (WiFi.status() != WL_CONNECTED && millis() - t0 < 20000) {
    delay(400);
    Serial.print(".");
  }
  if (WiFi.status() != WL_CONNECTED) {
    Serial.println(" FAILED - rebooting");
    delay(2000);
    ESP.restart();
  }
  Serial.println();
  Serial.print("IP: ");
  Serial.println(WiFi.localIP());

  server.on("/", handleRoot);
  server.on("/photo", handlePhoto);
  server.begin();
  Serial.println("HTTP server on :80");

  boot_ms = millis();
  Serial.printf("Warming up PIR for %lu ms\n", PIR_WARMUP_MS);
  blinkLed(5); // boot signal
}

void loop() {
  server.handleClient();

  unsigned long now = millis();
  if (now - boot_ms < PIR_WARMUP_MS) return;

  int pir = digitalRead(PIR_PIN);
  if (pir == HIGH && (now - last_trigger_ms) > TRIGGER_COOLDOWN_MS) {
    last_trigger_ms = now;
    Serial.println("PIR triggered - snapping photo");
    takePhoto();
  }
}
